INSERT INTO questions (id, exam_version_id, exam, skill, type_id, type_name, title, prompt, context_passage, audio_transcript, image_url, figure_data, model_answer, prep_time_seconds, time_limit_seconds, points, difficulty, explanation, tags, supported_exams, is_published) VALUES
    ('pte-b3-ra-001', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Oceanic Phytoplankton Cycles', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Marine phytoplankton play an essential role in regulating Earth''s climate by absorbing carbon dioxide through photosynthesis. When these microscopic organisms die, a significant portion of the organic carbon sinks into the deep ocean, sequestering greenhouse gases for centuries.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Group words into thought groups: pause slightly after ''climate'' and ''die''. Emphasize ''microscopic'' and ''sequestering''.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-002', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Metropolitan Avian Diversity', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Recent ecological surveys suggest that municipal parks support a surprisingly diverse array of avian species. Planting indigenous trees and preserving standing timber provide vital nesting cavities and sustenance, allowing bird populations to thrive alongside dense residential developments.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Maintain steady cadence through ''diverse array of avian species''. Articulate the final consonant clusters in ''developments''.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-003', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Silicon Solar Cell Design', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Engineers are currently developing advanced silicon solar cells that capture a wider spectrum of sunlight. Laboratory tests demonstrate that applying anti-reflective texturing to cell surfaces significantly improves overall photon absorption and power conversion efficiency.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Stress the first syllable in ''silicon'' and ''spectrum''. Keep a continuous rhythm without pausing awkwardly.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-004', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Subterranean Aquifer Dynamics', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Deep groundwater aquifers act as natural subterranean reservoirs, supplying freshwater to arid agricultural regions. During prolonged droughts, excessive extraction can permanently deplete porous bedrock storage, leading to regional land subsidence and diminished spring discharges.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Pronounce ''subterranean'' and ''subsidence'' distinctly. Maintain upward intonation on ''reservoirs'' and fall gently at the end.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-005', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Cognitive Reserve and Lifelong Learning', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Neurological research indicates that acquiring a second language enhances cognitive reserve, delaying the onset of age-related memory decline. Engaging in mentally demanding activities strengthens synaptic connections, promoting neurological resilience throughout adult life.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Ensure clear enunciation of ''synaptic'' and ''resilience''. Group ''age-related memory decline'' as a single fluent phrase.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-006', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Botanical Soil Phytoremediation', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Phytoremediation utilizes hyperaccumulating plants to extract toxic heavy metals from contaminated industrial soils. Certain species of alpine herbs concentrate nickel and zinc in their foliage, allowing hazardous contaminants to be safely harvested and processed.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Stress the syllables cleanly in ''phytoremediation'' and ''hyperaccumulating''. Pause naturally after ''soils''.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-007', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Marine Bioacoustics', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Underwater soundscapes provide critical orientation cues for larval invertebrates. Anthropogenic shipping noise frequently masks these natural acoustic signals, preventing young organisms from locating suitable rocky substrate for permanent settlement.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Emphasize ''anthropogenic'' and ''acoustic''. Ensure the contrast between natural cues and shipping noise is reflected in your pitch.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-008', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Stratospheric Ozone Recovery', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'International compliance with the Montreal Protocol has led to a measurable recovery of the stratospheric ozone layer. Phasing out chlorofluorocarbons has successfully reduced chlorine radicals, allowing natural chemical equilibrium to restore protective atmospheric concentrations.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Enunciate ''Montreal Protocol'' and ''chlorofluorocarbons'' clearly. Maintain fluent pacing across the entire second sentence.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-009', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Seismic Tomography Techniques', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Geophysicists employ seismic tomography to map the three-dimensional structure of Earth''s mantle. By recording variations in acoustic wave velocities generated by earthquakes, researchers can identify cold descending tectonic slabs and buoyant superplumes.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Deliver ''seismic tomography'' with steady pace. Emphasize ''three-dimensional'' and ''buoyant superplumes''.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-010', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Polymer Biodegradation Rates', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Synthetic bioplastics derived from polylactic acid require industrial composting facilities to degrade efficiently. Under standard ambient soil conditions, lack of elevated heat and specialized microbial enzymes results in degradation rates comparable to traditional petroleum plastics.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Stress ''polylactic acid'' and ''biodegradation''. Ensure distinct pronunciation of ''microbial enzymes''.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-011', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Ancient Cuneiform Tablets', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Mesopotamian scribes pressed wedge-shaped reeds into soft clay tablets to record administrative transactions and legal treaties. Baking these inscribed tablets in kilns rendered them impervious to fire and decay, preserving extensive primary historical archives.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Pronounce ''cuneiform'' and ''Mesopotamian'' accurately. Keep a rhythmic cadence through ''impervious to fire and decay''.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-012', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Volcanic Ash Soil Fertility', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Volcanic eruptions deposit tephra rich in primary minerals such as iron, magnesium, and potassium. Over geological timescales, weathering transforms volcanic ash into andisols, exceptionally fertile soils that sustain high agricultural productivity worldwide.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Enunciate chemical elements ''magnesium'' and ''potassium''. Stress ''weathering'' and ''agricultural productivity''.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-013', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Cellular Osmoregulation', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Freshwater organisms maintain internal osmotic balance by constantly expelling excess water through specialized contractile vacuoles. Without active ion transport mechanisms, surrounding hypotonic water would cause rapid cellular swelling and membrane lysis.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Articulate ''osmoregulation'' and ''contractile vacuoles'' cleanly. Fall smoothly in pitch at ''membrane lysis''.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-014', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Aerodynamic Wind Tunnel Testing', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Aeronautical engineers utilize scale models in wind tunnels to analyze boundary layer separation and induced drag. High-speed laser sensors detect airflow turbulence across wing surfaces, allowing winglets to be optimized for fuel efficiency.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Maintain an authoritative tone. Group ''boundary layer separation'' into a single fluent thought group.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-015', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Paleolithic Pigment Analysis', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Chemical spectroscopy reveals that early prehistoric artists blended powdered iron oxides with animal fats to manufacture stable pigments. Applying these durable mineral mixtures to dry limestone surfaces ensured their survival across tens of thousands of years.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Stress ''spectroscopy'' and ''iron oxides''. Enunciate ''tens of thousands of years'' with deliberate clarity.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-016', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Lithium Battery Degradation', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Repeated electrochemical cycling induces mechanical cracking within the cathode particles of lithium-ion batteries. Electrolyte decomposition progressively forms a resistive passivation layer, diminishing electrical storage capacity over time.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Enunciate ''electrochemical'' and ''passivation layer''. Emphasize the cause-and-effect relationship clearly.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-017', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Coastal Estuary Sedimentation', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Estuaries serve as natural depositional filters where river-borne silt encounters tidal marine currents. Flocculation causes suspended clay particles to aggregate into larger masses, which settle out rapidly and build extensive mudflats.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Pause slightly after ''filters''. Enunciate ''flocculation'' and ''aggregate'' with clear vowel definition.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-018', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Bacterial Antibiotic Resistance', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Horizontal gene transfer enables pathogenic bacteria to exchange resistance plasmids across divergent species. Overusing clinical antibiotics creates strong selective pressure, allowing multi-drug resistant strains to multiply unchecked in healthcare settings.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Stress ''horizontal gene transfer'' and ''resistance plasmids''. Speak deliberately through ''healthcare settings''.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-019', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Arid Flora Xerophytes', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Xerophytic vegetation survives extreme arid environments through sunken stomata and thick waxy cuticles that minimize transpirational moisture loss. Extensive radial root systems capture fleeting surface precipitation before it evaporates.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Pronounce ''xerophytic'' with a soft initial ''z'' sound. Articulate ''transpirational moisture loss'' smoothly.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-020', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Astrophysical Gravitational Lensing', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Massive galactic clusters warp the surrounding fabric of spacetime, bending light rays traveling from distant background objects. This gravitational lensing phenomenon magnifies faint primordial galaxies that would otherwise remain undetectable to terrestrial telescopes.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Emphasize ''spacetime'' and ''gravitational lensing''. Deliver the final clause with continuous fluent pacing.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-021', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Microbial Nitrogen Fixation', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Symbiotic rhizobia bacteria colonize root nodules of leguminous plants, converting atmospheric dinitrogen into bioavailable ammonia. In return, host plants supply photosynthetic carbohydrates, eliminating the necessity for synthetic nitrogen fertilizer.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Stress ''rhizobia'' and ''leguminous''. Ensure smooth transitions between scientific terminology.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-022', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Ceramic Thermal Barriers', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Modern gas turbines utilize plasma-sprayed ceramic thermal barrier coatings to protect underlying metallic alloy blades from extreme combustion temperatures. These porous ceramic layers enable turbine engines to operate above the melting point of superalloys.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Enunciate ''plasma-sprayed'' and ''superalloys''. Keep a confident, steady delivery throughout.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-023', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Benthic Abyssal Plain', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Covering more than half the ocean floor, abyssal plains represent vast, flat expanses blanketed by fine pelagic sediment. Despite near-freezing temperatures and immense hydrostatic pressure, diverse benthic detritivores thrive by scavenging organic marine snow.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Articulate ''hydrostatic pressure'' and ''benthic detritivores'' cleanly without pausing hesitantly.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-024', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Superconductor Resistance Loss', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'When specific crystalline alloys are cooled below their critical temperature, electrical resistivity drops abruptly to zero. Paired electrons flow smoothly through the crystal lattice without scattering, allowing electrical current to circulate indefinitely without energy loss.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Deliver ''electrical resistivity'' and ''indefinitely'' with clear, unstumbled articulation.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-025', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Archaeological Obsidian Sourcing', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Geochemical fingerprinting allows archaeologists to trace volcanic obsidian artifacts back to specific geological quarries. By measuring trace element concentrations using X-ray fluorescence, researchers reconstruct prehistoric maritime trade networks across the Mediterranean.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Stress ''fingerprinting'' and ''fluorescence''. Group ''prehistoric maritime trade networks'' as a fluent unit.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-026', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Volcanic Caldera Collapse', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'When a massive explosive eruption empties an underground magma chamber, the unsupported volcanic roof collapses downward. This rapid geological subsidence creates an expansive circular basin called a caldera, which often fills with water to form a crater lake.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Enunciate ''subsidence'' and ''caldera''. Fall gently in pitch on ''crater lake''.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-027', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Titanium Alloy Metallurgy', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Titanium alloys exhibit exceptional strength-to-weight ratios and outstanding corrosion resistance in marine environments. Adding small percentages of aluminum and vanadium stabilizes the crystal structure, making titanium indispensable for aerospace components.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Pronounce ''vanadium'' and ''corrosion resistance'' clearly. Maintain uniform pacing.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-028', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Subterranean Acoustic Resonance', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Natural subterranean limestone chambers act as acoustic resonators, selectively amplifying specific low-frequency sound waves. Early human societies frequently concentrated symbolic wall markings in cave niches that exhibited the most pronounced acoustic resonance.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Stress ''acoustic resonators'' and ''resonance''. Maintain natural pauses at punctuation marks.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-029', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Hydrodynamic Ship Hull Design', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Naval architects employ bulbous bows on commercial cargo vessels to modify the water flow around the forward hull. By generating an offsetting wave pattern, bulbous bows significantly reduce wave resistance and cut fuel consumption.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Deliver ''bulbous bows'' and ''hydrodynamic'' smoothly. Emphasize the energy-saving conclusion.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-030', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Tectonic Fault Creep', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'While some tectonic faults remain locked until releasing energy in sudden catastrophic earthquakes, others exhibit continuous aseismic fault creep. Slow, steady displacement along sliding rock boundaries prevents the accumulation of catastrophic tectonic elastic strain.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Articulate ''aseismic fault creep'' and ''elastic strain''. Keep a balanced tempo throughout.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-031', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Diatomaceous Silica Deposits', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Diatomaceous earth consists of fossilized microscopic silica skeletons shed by single-celled aquatic algae over millions of years. Because of its high porosity and chemically inert structure, it is widely utilized for industrial liquid filtration.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Stress ''diatomaceous'' and ''porosity''. Pronounce ''chemically inert'' with crisp consonants.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-032', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'High-Pressure Diamond Synthesis', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Industrial synthetic diamonds are manufactured by subjecting graphite to temperatures exceeding one thousand degrees Celsius under immense hydraulic pressure. The resulting diamond crystals possess identical hardness and thermal conductivity to natural gem-quality diamonds.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Enunciate ''hydraulic pressure'' and ''thermal conductivity'' clearly and fluently.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-033', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Enzyme Substrate Kinetics', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Enzymes catalyze biochemical reactions by lowering activation energy without undergoing permanent chemical alteration. When substrate molecules bind to the catalytic active site, precise conformational adjustments accelerate the conversion of reactants into metabolic products.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Deliver ''catalyze'' and ''conformational adjustments'' with steady academic phrasing.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-034', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Geomagnetic Field Reversals', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Paleomagnetic analysis of oceanic basalt demonstrates that Earth''s magnetic dipole reverses polarity at irregular geological intervals. Convective fluid circulation within the liquid iron outer core periodically destabilizes, causing magnetic poles to swap orientation.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Stress ''paleomagnetic'' and ''polarity''. Speak smoothly through ''liquid iron outer core''.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-035', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Optical Fiber Dispersion', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Chromatic dispersion in silica optical fibers causes light pulses of different wavelengths to propagate at slightly varying velocities. Over long transmission distances, pulse broadening can overlap neighboring data bits, necessitating optical dispersion compensation modules.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Articulate ''chromatic dispersion'' and ''velocities''. Ensure clear diction on technical nouns.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-036', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Atmospheric Inversion Formation', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'During clear winter nights, rapid terrestrial radiation cools ground-level air much faster than overlying atmospheric layers. This thermal inversion traps airborne particulate pollutants beneath a stagnant ceiling, worsening urban air quality until daytime solar heating resumes.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Pause naturally after ''layers''. Emphasize ''thermal inversion'' and ''stagnant ceiling''.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-037', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Sedimentary Varve Chronology', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Glacial lakes accumulate distinct paired sedimentary layers known as varves, comprising coarse light silt in summer and fine dark clay in winter. Counting these annual varves provides high-resolution geochronological dating extending back thousands of years.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Pronounce ''varves'' and ''geochronological'' distinctly. Maintain continuous rhythm.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-038', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Metamorphic Rock Foliation', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Under differential tectonic stress and high temperatures, platy minerals such as mica align perpendicular to the direction of maximum compressive force. This directional mineral alignment produces distinct planar banding known as metamorphic foliation.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Stress ''differential'' and ''foliation''. Articulate ''perpendicular'' with crisp consonant precision.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-039', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Microbial Fermentation Byproducts', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Anaerobic fermentation allows microorganisms to generate cellular adenosine triphosphate without molecular oxygen. In yeast, glycolytic pathways convert pyruvic acid into ethanol and carbon dioxide, a biochemical reaction utilized extensively in food biotechnology.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Deliver ''adenosine triphosphate'' and ''glycolytic'' without hesitating. Maintain an even pace.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-040', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Reinforced Composite Fibers', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Carbon-fiber-reinforced polymers combine lightweight epoxy resins with microscopic aligned strands of elemental carbon. These composite materials deliver exceptional stiffness and tensile strength, replacing heavy metallic structural frames in high-performance racing craft.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Stress ''carbon-fiber-reinforced'' and ''tensile strength''. End with clear down-pitch on ''craft''.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-041', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Sedimentary Cross-Bedding', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Ancient sand dunes and migrating river ripples preserve inclined sedimentary layering termed cross-bedding. Geologists analyze the angle and orientation of these inclined strata to determine paleocurrent directions and ancient prevailing wind patterns.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Enunciate ''cross-bedding'' and ''paleocurrent''. Group ''ancient prevailing wind patterns'' fluently.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-042', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Synthetic Aerogel Insulation', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Silica aerogels are synthetic ultra-lightweight solid materials in which the liquid component of a gel has been replaced with gas. Composed of over ninety percent air, aerogels possess extremely low thermal conductivity, serving as superior insulation for space probes.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Stress ''aerogels'' and ''insulation''. Enunciate ''low thermal conductivity'' smoothly.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-043', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Anthozoan Calcification Cycles', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Stony coral polyps extract calcium and bicarbonate ions from ambient seawater to precipitate crystalline aragonite skeletons. Over centuries, continuous upward accretion by millions of interconnected polyps forms massive wave-resistant limestone reef barriers.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Pronounce ''aragonite'' and ''accretion'' clearly. Maintain steady fluency across clauses.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-044', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Paleomagnetic Polarity Reversals', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'When basaltic magma cools along ocean ridges, ferromagnetic iron minerals lock in the orientation of Earth''s magnetic field. Alternating symmetrical bands of normal and reversed polarity preserved in seafloor crust provided crucial empirical confirmation for the theory of seafloor spreading.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Stress ''ferromagnetic'' and ''polarity''. Deliver ''confirmation'' and ''seafloor spreading'' with clear pausing.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-045', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Paleobotanical Pollen Grains', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Pollen grains possess exceptionally durable outer walls composed of sporopollenin, a natural polymer that resists chemical decay. Preserved in waterlogged lake sediments, ancient fossil pollen assemblages allow paleoclimatologists to reconstruct prehistoric regional vegetation shifts.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Enunciate ''sporopollenin'' and ''assemblages''. Maintain an informative, measured cadence.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-046', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Photolithography Semiconductor Etching', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Integrated circuit manufacturing relies on deep ultraviolet photolithography to pattern microscopic electronic circuitry onto silicon wafers. Light shining through photographic photomasks exposes chemical photoresist layers, guiding nanoscale chemical etching with extreme precision.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Deliver ''photolithography'' and ''photoresist'' with clean syllables and uninterrupted flow.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-047', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Acoustic Resonance in Strings', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'When a stretched musical string is plucked, standing transverse waves develop with stationary nodes and oscillating antinodes. The fundamental frequency of the acoustic pitch is determined by string tension, linear mass density, and vibrating length.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Stress ''antinodes'' and ''fundamental frequency''. Articulate physical variables clearly.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-048', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Tectonic Plate Rift Valleys', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Continental rifting initiates when ascending mantle plumes heat and fracture overlying continental lithosphere. Extensional tectonic forces pull tectonic plates apart, forming deep linear grabens bounded by steep fault scarps that gradually evolve into new ocean basins.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Pronounce ''grabens'' and ''lithosphere'' distinctly. Fall smoothly in pitch at the end.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-049', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Bacterial Biofilm Formation', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'Planktonic bacteria adhere to moist surfaces and secrete an extracellular matrix of polysaccharides and proteins. This collective biofilm shields bacterial colonies from antimicrobial agents and mechanical scouring, posing serious challenges for medical implant sterilization.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Enunciate ''extracellular matrix'' and ''polysaccharides''. Emphasize ''implant sterilization''.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
    ('pte-b3-ra-050', 'pte-2026-01', 'PTE', 'speaking', 'read-aloud', 'Read Aloud', 'Lunar Regolith Properties', 'Look at the text below. In 35 seconds, you must read this text aloud as naturally and clearly as possible. You have 40 seconds to read aloud.', 'The lunar regolith consists of pulverized basalt fragments and glass spherules generated by billions of years of meteorite impacts. Unweathered by water or wind, these jagged microscopic particles exhibit sharp abrasive edges and strong electrostatic adhesion.', NULL, NULL, NULL, NULL, 35, 40, 15, 'medium', 'Stress ''regolith'' and ''spherules''. Deliver the final list of traits with crisp enunciation.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Read Aloud'], ARRAY['PTE'], TRUE),
