    ('pte-b3-asq-037', 'pte-2026-01', 'PTE', 'speaking', 'pte-answer-short-question', 'Answer Short Questions', 'Science 24', 'You will hear a question. Please give a simple and short answer. Often just one or a few words is enough.', NULL, 'What do we call a scientist who studies animals?', NULL, NULL, 'A zoologist', 0, 10, 5, 'medium', 'Expected answer: A zoologist. Any natural equivalent is accepted.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Answer Short Questions'], ARRAY['PTE'], TRUE),
