    ('pte-b3-asq-039', 'pte-2026-01', 'PTE', 'speaking', 'pte-answer-short-question', 'Answer Short Questions', 'Time and numbers 17', 'You will hear a question. Please give a simple and short answer. Often just one or a few words is enough.', NULL, 'How many days are there in a week?', NULL, NULL, 'Seven', 0, 10, 5, 'medium', 'Expected answer: Seven. Any natural equivalent is accepted.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Answer Short Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-asq-040', 'pte-2026-01', 'PTE', 'speaking', 'pte-answer-short-question', 'Answer Short Questions', 'Time and numbers 18', 'You will hear a question. Please give a simple and short answer. Often just one or a few words is enough.', NULL, 'What is ten multiplied by ten?', NULL, NULL, 'One hundred', 0, 10, 5, 'medium', 'Expected answer: One hundred. Also: 100. Any natural equivalent is accepted.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Answer Short Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-asq-041', 'pte-2026-01', 'PTE', 'speaking', 'pte-answer-short-question', 'Answer Short Questions', 'Time and numbers 19', 'You will hear a question. Please give a simple and short answer. Often just one or a few words is enough.', NULL, 'How many wheels does a car usually have?', NULL, NULL, 'Four', 0, 10, 5, 'medium', 'Expected answer: Four. Any natural equivalent is accepted.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Answer Short Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-asq-042', 'pte-2026-01', 'PTE', 'speaking', 'pte-answer-short-question', 'Answer Short Questions', 'Time and numbers 20', 'You will hear a question. Please give a simple and short answer. Often just one or a few words is enough.', NULL, 'What is the last month of the year?', NULL, NULL, 'December', 0, 10, 5, 'medium', 'Expected answer: December. Any natural equivalent is accepted.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Answer Short Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-asq-043', 'pte-2026-01', 'PTE', 'speaking', 'pte-answer-short-question', 'Answer Short Questions', 'Time and numbers 21', 'You will hear a question. Please give a simple and short answer. Often just one or a few words is enough.', NULL, 'How many centimetres are there in a metre?', NULL, NULL, 'One hundred', 0, 10, 5, 'medium', 'Expected answer: One hundred. Also: 100. Any natural equivalent is accepted.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Answer Short Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-asq-044', 'pte-2026-01', 'PTE', 'speaking', 'pte-answer-short-question', 'Answer Short Questions', 'University life 15', 'You will hear a question. Please give a simple and short answer. Often just one or a few words is enough.', NULL, 'What do we call the last date by which an assignment must be handed in?', NULL, NULL, 'The deadline', 0, 10, 5, 'medium', 'Expected answer: The deadline. Any natural equivalent is accepted.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Answer Short Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-asq-045', 'pte-2026-01', 'PTE', 'speaking', 'pte-answer-short-question', 'Answer Short Questions', 'University life 16', 'You will hear a question. Please give a simple and short answer. Often just one or a few words is enough.', NULL, 'What do we call the list of topics covered in a course?', NULL, NULL, 'The syllabus', 0, 10, 5, 'medium', 'Expected answer: The syllabus. Also: the course outline. Any natural equivalent is accepted.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Answer Short Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-asq-046', 'pte-2026-01', 'PTE', 'speaking', 'pte-answer-short-question', 'Answer Short Questions', 'University life 17', 'You will hear a question. Please give a simple and short answer. Often just one or a few words is enough.', NULL, 'What do we call a meeting where one student discusses their work with a tutor?', NULL, NULL, 'A tutorial', 0, 10, 5, 'medium', 'Expected answer: A tutorial. Any natural equivalent is accepted.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Answer Short Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-asq-047', 'pte-2026-01', 'PTE', 'speaking', 'pte-answer-short-question', 'Answer Short Questions', 'University life 18', 'You will hear a question. Please give a simple and short answer. Often just one or a few words is enough.', NULL, 'What card do students show to get into the university library?', NULL, NULL, 'A student card', 0, 10, 5, 'medium', 'Expected answer: A student card. Also: a student ID. Any natural equivalent is accepted.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Answer Short Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-asq-048', 'pte-2026-01', 'PTE', 'speaking', 'pte-answer-short-question', 'Answer Short Questions', 'Nepal 11', 'You will hear a question. Please give a simple and short answer. Often just one or a few words is enough.', NULL, 'Which river flows through the city of Kathmandu?', NULL, NULL, 'The Bagmati', 0, 10, 5, 'medium', 'Expected answer: The Bagmati. Any natural equivalent is accepted.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Answer Short Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-asq-049', 'pte-2026-01', 'PTE', 'speaking', 'pte-answer-short-question', 'Answer Short Questions', 'Nepal 12', 'You will hear a question. Please give a simple and short answer. Often just one or a few words is enough.', NULL, 'Which lake in Pokhara is famous for its view of the mountains?', NULL, NULL, 'Phewa Lake', 0, 10, 5, 'medium', 'Expected answer: Phewa Lake. Any natural equivalent is accepted.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Answer Short Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-asq-050', 'pte-2026-01', 'PTE', 'speaking', 'pte-answer-short-question', 'Answer Short Questions', 'Nepal 13', 'You will hear a question. Please give a simple and short answer. Often just one or a few words is enough.', NULL, 'In which city is the Pashupatinath temple?', NULL, NULL, 'Kathmandu', 0, 10, 5, 'medium', 'Expected answer: Kathmandu. Any natural equivalent is accepted.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Answer Short Questions'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-001', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Campus Cycle Service Pod', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: I propose we install a self-service bicycle repair station near the central library with basic tools and an air pump. Blair: Tools left outside might get stolen or damaged by rain, and students might not know how to use them properly. Casey: We could mount weather-resistant tools on steel security cables under the existing covered bike shed and add a QR code linking to video tutorials. Blair: That would protect the equipment from weather and prevent theft while keeping it accessible around the clock. Alex: Let us submit a proposal to the campus facilities committee with a budget estimate for the covered shed installation.', NULL, NULL, 'Alex proposes: I propose we install a self-service bicycle repair station near the central library with basic tools and an air pump. Blair raises a concern: Tools left outside might get stolen or damaged by rain, and students might not know how to use them properly. Casey suggests a compromise: We could mount weather-resistant tools on steel security cables under the existing covered bike shed and add a QR code linking to video tutorials. The agreed next step is: Let us submit a proposal to the campus facilities committee with a budget estimate for the covered shed installation.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-002', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'A second-hand furniture exchange', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: At the end of every year, students throw away desks, lamps and chairs that are still in good condition, so I think we should run a free furniture exchange in the sports hall. Blair: The sports hall is booked for exams in June, and storing furniture over the summer would need space we simply don''t have. Casey: What if we held the exchange for just two days in the first week of September, when new students are arriving and looking for furniture? Blair: That works, because we would only need a room for two days and the furniture could go straight to new students. Alex: Let''s ask the accommodation office to collect donations in the halls and book a room for the first week of term.', NULL, NULL, 'Alex proposes: At the end of every year, students throw away desks, lamps and chairs that are still in good condition, so I think we should run a free furniture exchange in the sports hall. Blair raises a concern: The sports hall is booked for exams in June, and storing furniture over the summer would need space we simply don''t have. Casey suggests a compromise: What if we held the exchange for just two days in the first week of September, when new students are arriving and looking for furniture? The agreed next step is: Let''s ask the accommodation office to collect donations in the halls and book a room for the first week of term.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-003', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Student Society Web Portal Upgrade', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: Our student union website looks outdated, so we should hire an external agency to rebuild the entire platform from scratch. Blair: External web design agencies charge thousands of dollars that our annual student union budget simply cannot afford. Casey: We have dozens of talented computer science students who could redesign the frontend as a paid semester capstone project. Blair: That keeps the costs within our modest budget while providing valuable portfolio experience for our own students. Alex: I will reach out to the computer science department chair to ask about sponsoring a student project team.', NULL, NULL, 'Alex proposes: Our student union website looks outdated, so we should hire an external agency to rebuild the entire platform from scratch. Blair raises a concern: External web design agencies charge thousands of dollars that our annual student union budget simply cannot afford. Casey suggests a compromise: We have dozens of talented computer science students who could redesign the frontend as a paid semester capstone project. The agreed next step is: I will reach out to the computer science department chair to ask about sponsoring a student project team.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-004', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Dining Hall Organic Waste Sorting', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We ought to place organic compost collection bins next to every waste bin across all campus dining halls. Blair: Without proper oversight, students will contaminate compost bins with non-biodegradable plastic packaging and cutlery. Casey: We could start with a two-week pilot program in the main student cafeteria with student eco-reps standing by to guide disposal. Blair: A supervised pilot would allow us to evaluate contamination rates and educate diners before expanding campus-wide. Alex: I will coordinate with the dining hall manager to schedule the pilot launch for the start of next month.', NULL, NULL, 'Alex proposes: We ought to place organic compost collection bins next to every waste bin across all campus dining halls. Blair raises a concern: Without proper oversight, students will contaminate compost bins with non-biodegradable plastic packaging and cutlery. Casey suggests a compromise: We could start with a two-week pilot program in the main student cafeteria with student eco-reps standing by to guide disposal. The agreed next step is: I will coordinate with the dining hall manager to schedule the pilot launch for the start of next month.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-005', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Field Trip Rail Transit Option', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should charter two luxury coach buses to transport our sixty environmental science students to the coastal wetland reserve. Blair: Chartering private coach buses will deplete nearly half of our departmental field excursion fund for the semester. Casey: We could take the regional commuter rail directly to the coastal junction and walk the remaining kilometer along the nature trail. Blair: Group rail tickets offer a substantial student discount and walking the trail allows us to begin ecological observations earlier. Alex: I will book the group rail passes this afternoon and email the updated itinerary to all enrolled students.', NULL, NULL, 'Alex proposes: We should charter two luxury coach buses to transport our sixty environmental science students to the coastal wetland reserve. Blair raises a concern: Chartering private coach buses will deplete nearly half of our departmental field excursion fund for the semester. Casey suggests a compromise: We could take the regional commuter rail directly to the coastal junction and walk the remaining kilometer along the nature trail. The agreed next step is: I will book the group rail passes this afternoon and email the updated itinerary to all enrolled students.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-006', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Textbook Exchange Peer System', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: Let us create a physical textbook drop-off shelves in the student center where students can freely swap course books. Blair: Unmonitored shelves will quickly become cluttered with obsolete editions and damaged paperbacks that nobody wants. Casey: We could launch a moderated digital marketplace on our campus app where students list current editions and arrange direct handoffs. Blair: A digital exchange prevents physical clutter and ensures that listed books match currently required course syllabi. Alex: I will contact the campus app developer to see if they can enable a peer-to-peer textbook exchange tab.', NULL, NULL, 'Alex proposes: Let us create a physical textbook drop-off shelves in the student center where students can freely swap course books. Blair raises a concern: Unmonitored shelves will quickly become cluttered with obsolete editions and damaged paperbacks that nobody wants. Casey suggests a compromise: We could launch a moderated digital marketplace on our campus app where students list current editions and arrange direct handoffs. The agreed next step is: I will contact the campus app developer to see if they can enable a peer-to-peer textbook exchange tab.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-007', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Peer Tutoring Schedule Model', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: I suggest that peer math tutors hold walk-in drop-in clinics five afternoons a week in the science lobby. Blair: Walk-in sessions often result in long chaotic queues right before midterm exams while remaining completely empty during regular weeks. Casey: We could offer thirty-minute advance bookings online through the tutoring portal while reserving the final hour of each day for walk-ins. Blair: A hybrid booking system would balance tutor workloads evenly while still accommodating urgent last-minute questions. Alex: I will update the tutoring scheduling software to test this hybrid model starting next Monday.', NULL, NULL, 'Alex proposes: I suggest that peer math tutors hold walk-in drop-in clinics five afternoons a week in the science lobby. Blair raises a concern: Walk-in sessions often result in long chaotic queues right before midterm exams while remaining completely empty during regular weeks. Casey suggests a compromise: We could offer thirty-minute advance bookings online through the tutoring portal while reserving the final hour of each day for walk-ins. The agreed next step is: I will update the tutoring scheduling software to test this hybrid model starting next Monday.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-008', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Science Exhibition Stall Setup', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should invest our remaining grant funds into an expensive interactive digital touchscreen display for our science fair booth. Blair: Touchscreens are vulnerable to software glitches and outdoor glare, and they consume electricity our assigned outdoor stall lacks. Casey: We could build hands-on physical demonstration models using water pumps and sediment trays, accompanied by printed informational banners. Blair: Physical interactive models are far more engaging for visiting high school students and require zero electrical hookups. Alex: Let us draw up material lists for the sediment trays and purchase supplies from the university hardware store.', NULL, NULL, 'Alex proposes: We should invest our remaining grant funds into an expensive interactive digital touchscreen display for our science fair booth. Blair raises a concern: Touchscreens are vulnerable to software glitches and outdoor glare, and they consume electricity our assigned outdoor stall lacks. Casey suggests a compromise: We could build hands-on physical demonstration models using water pumps and sediment trays, accompanied by printed informational banners. The agreed next step is: Let us draw up material lists for the sediment trays and purchase supplies from the university hardware store.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-009', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Allowing pets in student housing', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: The university should allow students living in the halls to keep small pets such as fish or hamsters, because pets can help with loneliness. Blair: Some students have allergies, and animals left alone during the holidays could suffer or damage the rooms. Casey: We could run a trial in one building, allowing only small caged animals and fish, and require owners to arrange care for the holidays. Blair: A trial in one building would show whether the rules actually work before anything changes for everyone. Alex: Let''s survey residents about allergies first and then present the trial plan to the accommodation office.', NULL, NULL, 'Alex proposes: The university should allow students living in the halls to keep small pets such as fish or hamsters, because pets can help with loneliness. Blair raises a concern: Some students have allergies, and animals left alone during the holidays could suffer or damage the rooms. Casey suggests a compromise: We could run a trial in one building, allowing only small caged animals and fish, and require owners to arrange care for the holidays. The agreed next step is: Let''s survey residents about allergies first and then present the trial plan to the accommodation office.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-010', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'First-aid training for club leaders', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: Every sports club and society on campus should have at least two committee members trained in first aid before the start of each term. Blair: The full first-aid course costs money and takes two whole days, which many volunteers won''t be able to give up. Casey: The union could pay for the training, and small clubs with few physical activities could take the shorter half-day course instead. Blair: That seems fair, since the risk is much higher for the climbing club than for the chess society. Alex: Let''s draft a proposal for the union budget meeting and ask the health centre which courses they can run on campus.', NULL, NULL, 'Alex proposes: Every sports club and society on campus should have at least two committee members trained in first aid before the start of each term. Blair raises a concern: The full first-aid course costs money and takes two whole days, which many volunteers won''t be able to give up. Casey suggests a compromise: The union could pay for the training, and small clubs with few physical activities could take the shorter half-day course instead. The agreed next step is: Let''s draft a proposal for the union budget meeting and ask the health centre which courses they can run on campus.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-011', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Student Gallery Artwork Display', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should convert the unused basement storage room into a permanent contemporary gallery for student fine art submissions. Blair: The basement has poor ventilation, low ceilings, and minimal foot traffic, meaning very few visitors would ever see the artwork. Casey: Why not install professional hanging rails and spotlight fixtures along the sunlit corridors of the humanities building atrium? Blair: The atrium corridor receives hundreds of passing students and faculty daily, giving student artists maximum visibility. Alex: I will seek permission from the humanities department administrator to install hanging rails in the atrium.', NULL, NULL, 'Alex proposes: We should convert the unused basement storage room into a permanent contemporary gallery for student fine art submissions. Blair raises a concern: The basement has poor ventilation, low ceilings, and minimal foot traffic, meaning very few visitors would ever see the artwork. Casey suggests a compromise: Why not install professional hanging rails and spotlight fixtures along the sunlit corridors of the humanities building atrium? The agreed next step is: I will seek permission from the humanities department administrator to install hanging rails in the atrium.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-012', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Research Presentation Rehearsal Timing', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: Our symposium research team should rehearse the full slide presentation three times consecutively this evening. Blair: Running three full rehearsals in one evening will exhaust our presenters and leave no time to fix slide graphics. Casey: We should conduct one uninterrupted run-through tonight to check timing, compile constructive feedback, and do a final polish tomorrow. Blair: That allows us to pinpoint timing bottlenecks tonight without burning out before tomorrow''s conference. Alex: Let us start our single timed rehearsal right now and take detailed notes on each transition.', NULL, NULL, 'Alex proposes: Our symposium research team should rehearse the full slide presentation three times consecutively this evening. Blair raises a concern: Running three full rehearsals in one evening will exhaust our presenters and leave no time to fix slide graphics. Casey suggests a compromise: We should conduct one uninterrupted run-through tonight to check timing, compile constructive feedback, and do a final polish tomorrow. The agreed next step is: Let us start our single timed rehearsal right now and take detailed notes on each transition.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-013', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Laptop Loan Fleet Configuration', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: The university library should purchase one hundred high-end gaming laptops so students can borrow them for heavy computing tasks. Blair: Gaming laptops are heavy, expensive to insure, and have very short battery lives that make them impractical for class lectures. Casey: We could purchase lightweight ultrabooks with strong battery life and provide remote access credentials to the high-performance campus computing cluster. Blair: Cloud cluster access provides all the necessary computational power while keeping portable loan laptops affordable and lightweight. Alex: I will submit a proposal to the library technology committee recommending cluster-connected ultrabooks.', NULL, NULL, 'Alex proposes: The university library should purchase one hundred high-end gaming laptops so students can borrow them for heavy computing tasks. Blair raises a concern: Gaming laptops are heavy, expensive to insure, and have very short battery lives that make them impractical for class lectures. Casey suggests a compromise: We could purchase lightweight ultrabooks with strong battery life and provide remote access credentials to the high-performance campus computing cluster. The agreed next step is: I will submit a proposal to the library technology committee recommending cluster-connected ultrabooks.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-014', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Campus Evening Minivan Service', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should petition the transit office to run the student campus shuttle continuously every ten minutes throughout the night. Blair: Running empty full-sized diesel buses all night long would incur excessive fuel costs and cause unnecessary noise pollution. Casey: The transit office could operate an on-demand minivan service between midnight and dawn requested through the campus safety app. Blair: On-demand evening vans would guarantee safe transit for late-night lab workers while saving substantial operational expenses. Alex: I will write to the campus transit director proposing an on-demand evening shuttle trial.', NULL, NULL, 'Alex proposes: We should petition the transit office to run the student campus shuttle continuously every ten minutes throughout the night. Blair raises a concern: Running empty full-sized diesel buses all night long would incur excessive fuel costs and cause unnecessary noise pollution. Casey suggests a compromise: The transit office could operate an on-demand minivan service between midnight and dawn requested through the campus safety app. The agreed next step is: I will write to the campus transit director proposing an on-demand evening shuttle trial.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-015', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Student Garden Plot Lottery', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should allocate community garden plots on a first-come first-served basis starting at midnight on registration day. Blair: Midnight sign-ups disadvantage students without reliable internet access and favour those who can stay awake late. Casey: We could run a weighted lottery giving priority to students living in dormitories without balconies or private green space. Blair: A lottery ensures fair access for all applicants while prioritizing urban students who have no other gardening options. Alex: I will configure the online registration portal to run the weighted plot lottery next week.', NULL, NULL, 'Alex proposes: We should allocate community garden plots on a first-come first-served basis starting at midnight on registration day. Blair raises a concern: Midnight sign-ups disadvantage students without reliable internet access and favour those who can stay awake late. Casey suggests a compromise: We could run a weighted lottery giving priority to students living in dormitories without balconies or private green space. The agreed next step is: I will configure the online registration portal to run the weighted plot lottery next week.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-016', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Cinema Club Projector Rental', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: The film society should purchase a commercial theatrical projector to screen outdoor movies on the campus quadrangle lawn. Blair: Commercial outdoor cinema projectors cost thousands of dollars and we only hold outdoor screenings three times during the autumn term. Casey: We could rent high-lumen outdoor projection gear for those three specific event evenings and invest saved funds into film licensing. Blair: Renting equipment avoids depreciation and maintenance overhead while freeing funds to acquire higher quality classic film rights. Alex: I will request rental quotes from local audiovisual suppliers and present the numbers at our society meeting.', NULL, NULL, 'Alex proposes: The film society should purchase a commercial theatrical projector to screen outdoor movies on the campus quadrangle lawn. Blair raises a concern: Commercial outdoor cinema projectors cost thousands of dollars and we only hold outdoor screenings three times during the autumn term. Casey suggests a compromise: We could rent high-lumen outdoor projection gear for those three specific event evenings and invest saved funds into film licensing. The agreed next step is: I will request rental quotes from local audiovisual suppliers and present the numbers at our society meeting.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-017', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Engineering Indoor Drone Session', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should organize an open quadcopter drone racing tournament across the main campus lawn this weekend. Blair: High-speed drones flying over open pedestrian walkways pose significant safety hazards to passing students and violate campus airspace rules. Casey: We could reserve the indoor basketball gymnasium on Sunday morning and set up soft foam obstacle rings for a controlled workshop. Blair: The enclosed sports hall guarantees a wind-free environment, prevents stray flyaways, and keeps spectators completely safe. Alex: I will speak to the athletic director today to book the indoor gymnasium for our drone session.', NULL, NULL, 'Alex proposes: We should organize an open quadcopter drone racing tournament across the main campus lawn this weekend. Blair raises a concern: High-speed drones flying over open pedestrian walkways pose significant safety hazards to passing students and violate campus airspace rules. Casey suggests a compromise: We could reserve the indoor basketball gymnasium on Sunday morning and set up soft foam obstacle rings for a controlled workshop. The agreed next step is: I will speak to the athletic director today to book the indoor gymnasium for our drone session.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-018', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Orientation Cohort Walking Groups', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: Let us conduct our two-hour orientation walking tours with large groups of fifty incoming first-year students. Blair: Groups of fifty are too unwieldy; students at the back will struggle to hear the guide and will block crowded hallway corridors. Casey: We could recruit twelve senior student volunteers to lead smaller cohorts of twelve freshmen on staggered thirty-minute loops. Blair: Smaller cohorts allow for personalized questions, easier navigation through laboratory facilities, and better group bonding. Alex: I will post a volunteer recruitment notice for tour guides on the student leadership forum.', NULL, NULL, 'Alex proposes: Let us conduct our two-hour orientation walking tours with large groups of fifty incoming first-year students. Blair raises a concern: Groups of fifty are too unwieldy; students at the back will struggle to hear the guide and will block crowded hallway corridors. Casey suggests a compromise: We could recruit twelve senior student volunteers to lead smaller cohorts of twelve freshmen on staggered thirty-minute loops. The agreed next step is: I will post a volunteer recruitment notice for tour guides on the student leadership forum.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-019', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Study Abroad Booth Fair', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should invite thirty foreign university exchange representatives to speak in a single continuous five-hour auditorium lecture. Blair: A five-hour continuous lecture will overwhelm attendees with information and cause severe audience fatigue. Casey: We could host a two-hour interactive exhibition fair where representatives staff individual information tables and answer questions directly. Blair: An exhibition table format allows prospective exchange students to target universities relevant to their specific majors. Alex: I will reserve the multi-purpose student hall and send table registration forms to partner universities.', NULL, NULL, 'Alex proposes: We should invite thirty foreign university exchange representatives to speak in a single continuous five-hour auditorium lecture. Blair raises a concern: A five-hour continuous lecture will overwhelm attendees with information and cause severe audience fatigue. Casey suggests a compromise: We could host a two-hour interactive exhibition fair where representatives staff individual information tables and answer questions directly. The agreed next step is: I will reserve the multi-purpose student hall and send table registration forms to partner universities.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-020', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Coursework Synthesis Section Division', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: I think one person should write the entire twenty-page literature review so the writing style remains completely uniform. Blair: Assigning the entire literature review to one team member creates an unfair workload imbalance and risks missing the deadline. Casey: We could divide the review into four thematic sub-sections and designate one editor to harmonize voice, tone, and transitions. Blair: Splitting the research ensures equitable workload distribution while the designated editor ensures consistent stylistic flow. Alex: Let us assign the thematic sub-sections right now and agree on shared citation guidelines.', NULL, NULL, 'Alex proposes: I think one person should write the entire twenty-page literature review so the writing style remains completely uniform. Blair raises a concern: Assigning the entire literature review to one team member creates an unfair workload imbalance and risks missing the deadline. Casey suggests a compromise: We could divide the review into four thematic sub-sections and designate one editor to harmonize voice, tone, and transitions. The agreed next step is: Let us assign the thematic sub-sections right now and agree on shared citation guidelines.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-021', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Acoustic Study Carrel Retrofit', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should install four soundproof acoustic pods in the student lounge for students taking private remote job interviews. Blair: Acoustic phone pods are very expensive to purchase and will reduce open seating space needed for everyday socialization. Casey: The university could repurpose three underutilized study carrels on the library mezzanine into reservable interview booths. Blair: The library mezzanine is already quiet and retrofitting existing carrels with privacy acoustic screens is very economical. Alex: I will draft a formal request to the head of library facilities to pilot acoustic privacy screens.', NULL, NULL, 'Alex proposes: We should install four soundproof acoustic pods in the student lounge for students taking private remote job interviews. Blair raises a concern: Acoustic phone pods are very expensive to purchase and will reduce open seating space needed for everyday socialization. Casey suggests a compromise: The university could repurpose three underutilized study carrels on the library mezzanine into reservable interview booths. The agreed next step is: I will draft a formal request to the head of library facilities to pilot acoustic privacy screens.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-022', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Greenhouse Diurnal Thermostat Program', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should keep the botanical research greenhouse heated to twenty-five degrees Celsius continuously throughout the entire winter. Blair: Continuous high heating will result in exorbitant energy bills and fails to replicate natural diurnal temperature fluctuations. Casey: We could program automated thermostats to maintain twenty-two degrees during daytime hours and drop to sixteen degrees overnight. Blair: A nighttime temperature drop mirrors natural ecological rhythms, improves plant stem rigidity, and reduces natural gas consumption. Alex: I will calibrate the digital greenhouse heating controller to follow the diurnal schedule.', NULL, NULL, 'Alex proposes: We should keep the botanical research greenhouse heated to twenty-five degrees Celsius continuously throughout the entire winter. Blair raises a concern: Continuous high heating will result in exorbitant energy bills and fails to replicate natural diurnal temperature fluctuations. Casey suggests a compromise: We could program automated thermostats to maintain twenty-two degrees during daytime hours and drop to sixteen degrees overnight. The agreed next step is: I will calibrate the digital greenhouse heating controller to follow the diurnal schedule.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-023', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Robotics Component Procurement Strategy', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should order all our competition robotic motors and sensors from an overseas supplier offering fifty percent discounts. Blair: Overseas maritime shipping takes six to eight weeks and customs delays could cause us to miss our national competition registration. Casey: We could order critical microcontrollers and core motors from a local domestic supplier and order secondary aesthetic brackets from overseas. Blair: Splitting the order ensures we can begin core chassis assembly immediately without jeopardizing competition deadlines. Alex: I will place the domestic order for motors today and arrange the bracket shipment right afterward.', NULL, NULL, 'Alex proposes: We should order all our competition robotic motors and sensors from an overseas supplier offering fifty percent discounts. Blair raises a concern: Overseas maritime shipping takes six to eight weeks and customs delays could cause us to miss our national competition registration. Casey suggests a compromise: We could order critical microcontrollers and core motors from a local domestic supplier and order secondary aesthetic brackets from overseas. The agreed next step is: I will place the domestic order for motors today and arrange the bracket shipment right afterward.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-024', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Starting a campus choir', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: I''d like the music society to start a campus choir that anyone can join, with no audition, meeting every Wednesday evening. Blair: Without auditions, the standard might be too mixed, and people who can already sing well could become frustrated and leave. Casey: We could have one open choir for everyone and a smaller group that performs at events, which people could try out for later in the year. Blair: Good, that keeps the choir welcoming while still giving experienced singers a challenge. Alex: Let''s put up posters for a first open session next month and ask one of the music lecturers to lead it.', NULL, NULL, 'Alex proposes: I''d like the music society to start a campus choir that anyone can join, with no audition, meeting every Wednesday evening. Blair raises a concern: Without auditions, the standard might be too mixed, and people who can already sing well could become frustrated and leave. Casey suggests a compromise: We could have one open choir for everyone and a smaller group that performs at events, which people could try out for later in the year. The agreed next step is: Let''s put up posters for a first open session next month and ask one of the music lecturers to lead it.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-025', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Discipline Specific Resume Clinic', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should require all graduating seniors to attend a mandatory four-hour resume formatting lecture in the main hall. Blair: Mandatory general lectures are poorly attended and generic resume advice often fails to address industry-specific technical requirements. Casey: We could offer thirty-minute discipline-specific peer review clinics organized by engineering, humanities, and business student societies. Blair: Tailored industry clinics provide actionable feedback relevant to specific employer expectations and portfolio standards. Alex: I will coordinate with the departmental student societies to schedule their individual resume clinics.', NULL, NULL, 'Alex proposes: We should require all graduating seniors to attend a mandatory four-hour resume formatting lecture in the main hall. Blair raises a concern: Mandatory general lectures are poorly attended and generic resume advice often fails to address industry-specific technical requirements. Casey suggests a compromise: We could offer thirty-minute discipline-specific peer review clinics organized by engineering, humanities, and business student societies. The agreed next step is: I will coordinate with the departmental student societies to schedule their individual resume clinics.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-026', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'A student cookery class', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: Lots of first-year students live on instant noodles, so I think the union should run a weekly cookery class teaching simple, cheap meals. Blair: The kitchens in the halls are tiny, and there would be safety problems with twenty people cooking at once. Casey: The catering department''s training kitchen is empty on Sunday afternoons, and students could pay a small fee to cover the ingredients. Blair: That solves the space problem, and a small fee means people are more likely to actually turn up. Alex: Let''s ask the catering manager about using the kitchen and find a student volunteer who can teach the first session.', NULL, NULL, 'Alex proposes: Lots of first-year students live on instant noodles, so I think the union should run a weekly cookery class teaching simple, cheap meals. Blair raises a concern: The kitchens in the halls are tiny, and there would be safety problems with twenty people cooking at once. Casey suggests a compromise: The catering department''s training kitchen is empty on Sunday afternoons, and students could pay a small fee to cover the ingredients. The agreed next step is: Let''s ask the catering manager about using the kitchen and find a student volunteer who can teach the first session.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-027', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Student Media Podcast Production', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: The student radio station should broadcast daily live three-hour political debate panels covering global international affairs. Blair: Producing a daily three-hour live broadcast requires immense research time that full-time student volunteers cannot sustain. Casey: We could produce a weekly forty-minute recorded podcast focusing on campus research discoveries and student community initiatives. Blair: A weekly recorded podcast allows for polished audio editing, consistent quality, and manageable volunteer commitment. Alex: I will draft a production schedule for a weekly podcast pilot and pitch it to the station manager.', NULL, NULL, 'Alex proposes: The student radio station should broadcast daily live three-hour political debate panels covering global international affairs. Blair raises a concern: Producing a daily three-hour live broadcast requires immense research time that full-time student volunteers cannot sustain. Casey suggests a compromise: We could produce a weekly forty-minute recorded podcast focusing on campus research discoveries and student community initiatives. The agreed next step is: I will draft a production schedule for a weekly podcast pilot and pitch it to the station manager.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-028', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Solar Bench Pilot Installation', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should replace every standard wooden bench on the central campus quad with solar-powered device charging benches. Blair: Solar charging benches are costly to install and cloudy winter weather will render their integrated USB ports useless for months. Casey: We could install three solar benches outside the student cafeteria where sunlight is optimal, and evaluate usage before expanding. Blair: A focused three-bench installation lets us measure student demand and battery performance without overcommitting capital. Alex: I will contact the green campus fund to apply for a small grant covering the three pilot benches.', NULL, NULL, 'Alex proposes: We should replace every standard wooden bench on the central campus quad with solar-powered device charging benches. Blair raises a concern: Solar charging benches are costly to install and cloudy winter weather will render their integrated USB ports useless for months. Casey suggests a compromise: We could install three solar benches outside the student cafeteria where sunlight is optimal, and evaluate usage before expanding. The agreed next step is: I will contact the green campus fund to apply for a small grant covering the three pilot benches.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-029', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Moot Court Tournament Hosting', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should book the downtown municipal convention center auditorium to host our regional inter-university debate tournament. Blair: The convention center requires expensive commercial insurance, high deposit fees, and involves inconvenient transit for visiting teams. Casey: We can host the preliminary debates across law school seminar rooms and book the law moot court for the grand final. Blair: Utilizing campus law classrooms is free of charge, fully equipped with podiums, and easily accessible from student dorms. Alex: I will confirm room reservations with the law faculty administrator by the end of the week.', NULL, NULL, 'Alex proposes: We should book the downtown municipal convention center auditorium to host our regional inter-university debate tournament. Blair raises a concern: The convention center requires expensive commercial insurance, high deposit fees, and involves inconvenient transit for visiting teams. Casey suggests a compromise: We can host the preliminary debates across law school seminar rooms and book the law moot court for the grand final. The agreed next step is: I will confirm room reservations with the law faculty administrator by the end of the week.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-030', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Laboratory Protocol Poster Competition', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should mandate that all second-year chemistry students design and submit a laboratory safety poster for graded course credit. Blair: Making artistic poster creation mandatory and graded may provoke resentment from students who struggle with visual graphic design. Casey: We could turn it into an optional voluntary competition offering bookstore vouchers and laboratory supply prizes for the top three posters. Blair: A prize competition will motivate creative entries organically while keeping coursework assessments focused strictly on chemical science. Alex: I will announce the voluntary safety poster contest on the chemistry department noticeboard tomorrow.', NULL, NULL, 'Alex proposes: We should mandate that all second-year chemistry students design and submit a laboratory safety poster for graded course credit. Blair raises a concern: Making artistic poster creation mandatory and graded may provoke resentment from students who struggle with visual graphic design. Casey suggests a compromise: We could turn it into an optional voluntary competition offering bookstore vouchers and laboratory supply prizes for the top three posters. The agreed next step is: I will announce the voluntary safety poster contest on the chemistry department noticeboard tomorrow.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-031', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Amphitheater Screening Arrangement', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: Let us host our annual student society outdoor movie night on the open athletic sports turf field. Blair: Heavy projector equipment, chairs, and hundreds of students will damage the delicate synthetic turf, causing hefty athletic fines. Casey: We could set up the inflatable projector screen on the concrete amphitheater behind the arts building where stepped seating already exists. Blair: The concrete amphitheater provides natural tiered seating, eliminates equipment damage, and has direct outdoor power outlets. Alex: I will inspect the amphitheater power outlets tomorrow and reserve the outdoor space with campus scheduling.', NULL, NULL, 'Alex proposes: Let us host our annual student society outdoor movie night on the open athletic sports turf field. Blair raises a concern: Heavy projector equipment, chairs, and hundreds of students will damage the delicate synthetic turf, causing hefty athletic fines. Casey suggests a compromise: We could set up the inflatable projector screen on the concrete amphitheater behind the arts building where stepped seating already exists. The agreed next step is: I will inspect the amphitheater power outlets tomorrow and reserve the outdoor space with campus scheduling.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-032', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Language Partner Intake Matching', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should pair domestic and international language exchange partners randomly using an automated spreadsheet algorithm. Blair: Purely random pairings often result in mismatched schedules, conflicting fluency levels, and partners who share zero academic interests. Casey: We could administer a brief intake questionnaire matching students by target language, preferred meeting times, and mutual hobbies. Blair: Matching shared interests and compatible weekly availability dramatically improves long-term language partnership retention. Alex: I will create a Google Form questionnaire and distribute it to all foreign language department classes.', NULL, NULL, 'Alex proposes: We should pair domestic and international language exchange partners randomly using an automated spreadsheet algorithm. Blair raises a concern: Purely random pairings often result in mismatched schedules, conflicting fluency levels, and partners who share zero academic interests. Casey suggests a compromise: We could administer a brief intake questionnaire matching students by target language, preferred meeting times, and mutual hobbies. The agreed next step is: I will create a Google Form questionnaire and distribute it to all foreign language department classes.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-033', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'A free printing allowance', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: Every student should get a free allowance of two hundred printed pages each term, because printing costs add up quickly. Blair: If printing is free, people may print far more than they need, which wastes paper and money. Casey: We could make the allowance smaller, say one hundred pages, and encourage lecturers to share notes online so there is less need to print. Blair: That balances the cost for students with the need to reduce waste. Alex: Let''s ask the IT office how much the allowance would cost and put the idea to the student council.', NULL, NULL, 'Alex proposes: Every student should get a free allowance of two hundred printed pages each term, because printing costs add up quickly. Blair raises a concern: If printing is free, people may print far more than they need, which wastes paper and money. Casey suggests a compromise: We could make the allowance smaller, say one hundred pages, and encourage lecturers to share notes online so there is less need to print. The agreed next step is: Let''s ask the IT office how much the allowance would cost and put the idea to the student council.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-034', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Open Source Indoor Navigation Mapping', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should hire a commercial software development firm to build a bespoke mobile indoor navigation app for our campus. Blair: Proprietary navigation software requires continuous licensing fees and frequent expensive maintenance contracts whenever room layouts change. Casey: We could collaborate with the student open-source mapping club to digitize building floor plans directly into OpenStreetMap. Blair: OpenStreetMap is free, open-source, and allows student volunteers to update room numbers and accessibility ramps instantly. Alex: I will schedule a meeting with the campus mapping club president to discuss mapping indoor corridors.', NULL, NULL, 'Alex proposes: We should hire a commercial software development firm to build a bespoke mobile indoor navigation app for our campus. Blair raises a concern: Proprietary navigation software requires continuous licensing fees and frequent expensive maintenance contracts whenever room layouts change. Casey suggests a compromise: We could collaborate with the student open-source mapping club to digitize building floor plans directly into OpenStreetMap. The agreed next step is: I will schedule a meeting with the campus mapping club president to discuss mapping indoor corridors.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-035', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Campus Flora Inventory BioBlitz', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: The biology department should hire private environmental ecological consultants to conduct an exhaustive botanical audit of campus trees. Blair: Hiring private environmental consultants will cost tens of thousands of dollars that could be better spent on student research scholarships. Casey: We could organize a weekend BioBlitz where biology students and amateur naturalist volunteers catalog species using mobile identification apps. Blair: A citizen science BioBlitz engages the student community, provides field taxonomy experience, and generates comprehensive biodiversity records for free. Alex: I will coordinate with the ecology professors to schedule the BioBlitz for the upcoming Earth Day weekend.', NULL, NULL, 'Alex proposes: The biology department should hire private environmental ecological consultants to conduct an exhaustive botanical audit of campus trees. Blair raises a concern: Hiring private environmental consultants will cost tens of thousands of dollars that could be better spent on student research scholarships. Casey suggests a compromise: We could organize a weekend BioBlitz where biology students and amateur naturalist volunteers catalog species using mobile identification apps. The agreed next step is: I will coordinate with the ecology professors to schedule the BioBlitz for the upcoming Earth Day weekend.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-036', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Student Gazette Digital Format', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should double our monthly print run of the student newspaper to four thousand physical paper copies. Blair: Most printed student newspapers end up unread in recycling bins because students overwhelmingly read news articles on mobile phones. Casey: We should maintain a modest print run of eight hundred commemorative copies and invest our budget into a modern digital mobile newsletter. Blair: Prioritizing the digital newsletter expands readership dramatically while reducing paper waste and printing expenditures. Alex: I will present the digital newsletter strategy at the editorial board meeting this Thursday.', NULL, NULL, 'Alex proposes: We should double our monthly print run of the student newspaper to four thousand physical paper copies. Blair raises a concern: Most printed student newspapers end up unread in recycling bins because students overwhelmingly read news articles on mobile phones. Casey suggests a compromise: We should maintain a modest print run of eight hundred commemorative copies and invest our budget into a modern digital mobile newsletter. The agreed next step is: I will present the digital newsletter strategy at the editorial board meeting this Thursday.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-037', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Maker Space Print Job Scheduling', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: Students should be allowed to run twenty-four-hour continuous 3D prints on maker space printers without prior staff approval. Blair: Unsupervised overnight prints frequently fail, wasting kilograms of filament and creating acute thermal fire hazards in the workshop. Casey: We should require all print jobs exceeding four hours to be vetted by a workshop technician and scheduled during supervised operational hours. Blair: Technician review ensures slicing settings are correct, avoids nozzle clogs, and guarantees workshop safety. Alex: I will update the maker space printing safety protocols and post the new guidelines next to the printers.', NULL, NULL, 'Alex proposes: Students should be allowed to run twenty-four-hour continuous 3D prints on maker space printers without prior staff approval. Blair raises a concern: Unsupervised overnight prints frequently fail, wasting kilograms of filament and creating acute thermal fire hazards in the workshop. Casey suggests a compromise: We should require all print jobs exceeding four hours to be vetted by a workshop technician and scheduled during supervised operational hours. The agreed next step is: I will update the maker space printing safety protocols and post the new guidelines next to the printers.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-038', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Student Wellness Activity Roster', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should mandate that all academic faculty cancel their Friday afternoon classes so all students attend a mental wellness lecture. Blair: Canceling mandatory laboratory and lecture classes disrupts course accreditation requirements and will face strong faculty resistance. Casey: We could host a series of thirty-minute wellness drop-in sessions, meditation workshops, and therapy dog visits in the student union throughout the week. Blair: Offering diverse, flexible wellness activities throughout the week enables students to participate without missing scheduled academic classes. Alex: I will contact certified therapy dog organizations and book the student union multipurpose rooms for the wellness week.', NULL, NULL, 'Alex proposes: We should mandate that all academic faculty cancel their Friday afternoon classes so all students attend a mental wellness lecture. Blair raises a concern: Canceling mandatory laboratory and lecture classes disrupts course accreditation requirements and will face strong faculty resistance. Casey suggests a compromise: We could host a series of thirty-minute wellness drop-in sessions, meditation workshops, and therapy dog visits in the student union throughout the week. The agreed next step is: I will contact certified therapy dog organizations and book the student union multipurpose rooms for the wellness week.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-039', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Engineering Atrium Poster Panels', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should rent the downtown exhibition center hall to display eighty graduate research posters during the annual symposium. Blair: Paying commercial hall rental fees is an unnecessary expense when university campus spaces can easily accommodate our symposium. Casey: We could set up modular poster display boards along the natural lighting atrium of the new engineering complex. Blair: The engineering atrium provides a modern, spacious backdrop with high foot traffic from visiting researchers and faculty. Alex: I will submit a facility reservation request for the engineering atrium display boards.', NULL, NULL, 'Alex proposes: We should rent the downtown exhibition center hall to display eighty graduate research posters during the annual symposium. Blair raises a concern: Paying commercial hall rental fees is an unnecessary expense when university campus spaces can easily accommodate our symposium. Casey suggests a compromise: We could set up modular poster display boards along the natural lighting atrium of the new engineering complex. The agreed next step is: I will submit a facility reservation request for the engineering atrium display boards.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-040', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Feline Welfare Managed Shelters', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: The student council should purchase feeding bowls and distribute food for stray campus cats across all academic lawns. Blair: Scattering feeding stations haphazardly attracts raccoons, rodents, and insects, creating sanitary problems near classroom doors. Casey: We should partner with a local veterinary charity to set up a managed trap-neuter-vaccinate-return program with designated shelter stations. Blair: A formal veterinary partnership humanely stabilizes the stray animal population while keeping feeding areas hygienic and controlled. Alex: I will reach out to the municipal animal shelter to draft a humane management agreement for the campus.', NULL, NULL, 'Alex proposes: The student council should purchase feeding bowls and distribute food for stray campus cats across all academic lawns. Blair raises a concern: Scattering feeding stations haphazardly attracts raccoons, rodents, and insects, creating sanitary problems near classroom doors. Casey suggests a compromise: We should partner with a local veterinary charity to set up a managed trap-neuter-vaccinate-return program with designated shelter stations. The agreed next step is: I will reach out to the municipal animal shelter to draft a humane management agreement for the campus.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-041', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Intramural Gear Keypad Access', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should leave the athletic equipment shed unlocked during the day so any student can borrow soccer balls and cones freely. Blair: Leaving the shed unlocked has previously led to stolen gear, damaged equipment, and sports teams finding no balls for scheduled matches. Casey: We can install an electronic keypad lock and issue student ID access cards tied to an online check-out log system. Blair: Electronic access holds borrowers accountable for returning items while allowing convenient access for registered club members. Alex: I will ask campus security to install a card reader on the athletic equipment shed door.', NULL, NULL, 'Alex proposes: We should leave the athletic equipment shed unlocked during the day so any student can borrow soccer balls and cones freely. Blair raises a concern: Leaving the shed unlocked has previously led to stolen gear, damaged equipment, and sports teams finding no balls for scheduled matches. Casey suggests a compromise: We can install an electronic keypad lock and issue student ID access cards tied to an online check-out log system. The agreed next step is: I will ask campus security to install a card reader on the athletic equipment shed door.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-042', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Observatory Meadow Telescope Night', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should organize our public stargazing telescope night on the rooftop terrace of the administration tower. Blair: The administration tower terrace lacks protective high safety railings and has bright decorative architectural spotlights that cause severe light pollution. Casey: We could hold the event at the university observatory meadow on the western edge of campus where ambient lighting is shielded. Blair: The observatory meadow offers unobstructed dark sky horizons, soft grass for spectators, and meets all campus safety guidelines. Alex: I will confirm the observatory meadow booking with the astronomy department director.', NULL, NULL, 'Alex proposes: We should organize our public stargazing telescope night on the rooftop terrace of the administration tower. Blair raises a concern: The administration tower terrace lacks protective high safety railings and has bright decorative architectural spotlights that cause severe light pollution. Casey suggests a compromise: We could hold the event at the university observatory meadow on the western edge of campus where ambient lighting is shielded. The agreed next step is: I will confirm the observatory meadow booking with the astronomy department director.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-043', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Artisan Market Table Registration', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should charge student artisans a fifty-dollar registration fee to set up craft stalls at the annual spring carnival. Blair: A fifty-dollar fee is too prohibitive for student hobbyists selling handmade stickers, ceramics, or knitted scarves. Casey: We could charge a nominal ten-dollar table fee or take a five percent voluntary contribution from stalls that generate over one hundred dollars. Blair: A low entry fee encourages wide student participation while still covering the minor costs of renting market tables. Alex: I will revise the artisan registration form to reflect the ten-dollar table reservation fee.', NULL, NULL, 'Alex proposes: We should charge student artisans a fifty-dollar registration fee to set up craft stalls at the annual spring carnival. Blair raises a concern: A fifty-dollar fee is too prohibitive for student hobbyists selling handmade stickers, ceramics, or knitted scarves. Casey suggests a compromise: We could charge a nominal ten-dollar table fee or take a five percent voluntary contribution from stalls that generate over one hundred dollars. The agreed next step is: I will revise the artisan registration form to reflect the ten-dollar table reservation fee.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-044', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Midday Commons Candidate Debate', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should hold the presidential election debate in the campus amphitheater at eight o''clock on a Friday evening. Blair: Friday evening attendance will be extremely low as most commuting students leave campus by five in the afternoon. Casey: We should host the debate during the universal free hour on Wednesday at noon in the central dining commons. Blair: Holding the debate during lunchtime ensures a large, diverse audience of eating students who can engage directly with candidates. Alex: I will book the dining commons stage and test the wireless microphones for Wednesday noon.', NULL, NULL, 'Alex proposes: We should hold the presidential election debate in the campus amphitheater at eight o''clock on a Friday evening. Blair raises a concern: Friday evening attendance will be extremely low as most commuting students leave campus by five in the afternoon. Casey suggests a compromise: We should host the debate during the universal free hour on Wednesday at noon in the central dining commons. The agreed next step is: I will book the dining commons stage and test the wireless microphones for Wednesday noon.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-045', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Hydrological Sampling Transect Plan', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: Our environmental research team should collect water samples from fifty different points along the river in a single day. Blair: Sampling fifty points across twenty miles in one day will result in rushed handling, contaminated samples, and team exhaustion. Casey: We should select fifteen representative hydrological transects and conduct rigorous multi-depth sampling over a three-day weekend. Blair: A focused three-day sampling strategy guarantees meticulous sample preservation, sterile controls, and higher data integrity. Alex: I will map out the fifteen hydrological transects and prepare sterile glass sample containers.', NULL, NULL, 'Alex proposes: Our environmental research team should collect water samples from fifty different points along the river in a single day. Blair raises a concern: Sampling fifty points across twenty miles in one day will result in rushed handling, contaminated samples, and team exhaustion. Casey suggests a compromise: We should select fifteen representative hydrological transects and conduct rigorous multi-depth sampling over a three-day weekend. The agreed next step is: I will map out the fifteen hydrological transects and prepare sterile glass sample containers.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-046', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Indigenous Woodland Sapling Sourcing', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should plant five hundred fast-growing non-native eucalyptus saplings across the university nature conservation zone. Blair: Non-native eucalyptus trees consume massive amounts of groundwater, acidify topsoil, and increase wild brushfire hazards. Casey: We should source native oak, birch, and hazel saplings from a local conservation nursery to restore indigenous woodland biodiversity. Blair: Planting native deciduous species supports indigenous pollinators, enhances soil fungal networks, and creates resilient natural habitats. Alex: I will contact the provincial forestry service to order three hundred native saplings for our planting drive.', NULL, NULL, 'Alex proposes: We should plant five hundred fast-growing non-native eucalyptus saplings across the university nature conservation zone. Blair raises a concern: Non-native eucalyptus trees consume massive amounts of groundwater, acidify topsoil, and increase wild brushfire hazards. Casey suggests a compromise: We should source native oak, birch, and hazel saplings from a local conservation nursery to restore indigenous woodland biodiversity. The agreed next step is: I will contact the provincial forestry service to order three hundred native saplings for our planting drive.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-047', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Alumni Tech Venture Sponsorship', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should email generic sponsorship solicitations to five hundred technology companies found on public web directories. Blair: Sending hundreds of generic mass emails will be flagged as spam and yields virtually zero response from corporate recruiters. Casey: We should craft personalized sponsorship proposals targeting thirty regional tech firms and alumni-founded startups that actively recruit on campus. Blair: Targeting alumni and active campus recruiters builds meaningful relationships and yields much higher financial and mentorship commitments. Alex: I will compile a shortlist of thirty alumni-led tech companies and customize our sponsorship proposal deck.', NULL, NULL, 'Alex proposes: We should email generic sponsorship solicitations to five hundred technology companies found on public web directories. Blair raises a concern: Sending hundreds of generic mass emails will be flagged as spam and yields virtually zero response from corporate recruiters. Casey suggests a compromise: We should craft personalized sponsorship proposals targeting thirty regional tech firms and alumni-founded startups that actively recruit on campus. The agreed next step is: I will compile a shortlist of thirty alumni-led tech companies and customize our sponsorship proposal deck.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-048', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Security Centralized Lost Item Log', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: Every academic department should maintain its own independent cardboard box for lost items in their main office. Blair: Decentralized cardboard boxes make it nearly impossible for students to locate lost keys or electronics across thirty campus buildings. Casey: We should establish a centralized lost and found desk at the campus security headquarters with an online photo inventory database. Blair: A centralized digital inventory allows students to search for lost belongings online and verify ownership before claiming them. Alex: I will coordinate with campus security to launch the searchable lost-and-found web portal.', NULL, NULL, 'Alex proposes: Every academic department should maintain its own independent cardboard box for lost items in their main office. Blair raises a concern: Decentralized cardboard boxes make it nearly impossible for students to locate lost keys or electronics across thirty campus buildings. Casey suggests a compromise: We should establish a centralized lost and found desk at the campus security headquarters with an online photo inventory database. The agreed next step is: I will coordinate with campus security to launch the searchable lost-and-found web portal.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-049', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Glass Pavilion Society Reception', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should rent a luxury downtown hotel banquet hall for our end-of-term student society gala dinner. Blair: Hotel banquet halls require high ticket prices of over sixty dollars per student, excluding many members with limited budgets. Casey: We can host the gala in the renovated student union glass pavilion with catered hot finger food and student musical performances. Blair: Using the campus pavilion keeps ticket prices under fifteen dollars, ensuring that all society members can celebrate together. Alex: I will place a reservation on the student union glass pavilion and contact student catering services.', NULL, NULL, 'Alex proposes: We should rent a luxury downtown hotel banquet hall for our end-of-term student society gala dinner. Blair raises a concern: Hotel banquet halls require high ticket prices of over sixty dollars per student, excluding many members with limited budgets. Casey suggests a compromise: We can host the gala in the renovated student union glass pavilion with catered hot finger food and student musical performances. The agreed next step is: I will place a reservation on the student union glass pavilion and contact student catering services.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-sgd-050', 'pte-2026-01', 'PTE', 'speaking', 'pte-summarise-group-discussion', 'Summarise Group Discussion', 'Undergraduate Manuscript Formatting', 'You will hear three people having a discussion. When you hear the beep, summarise the whole discussion. You will have 10 seconds to prepare and 2 minutes to give your response. (Practice note: this discussion is shorter than in the real test.)', NULL, 'Alex: We should require all undergraduate journal authors to submit manuscripts exclusively in LaTeX formatting. Blair: Most humanities and social science undergraduates have never used LaTeX and will be discouraged from submitting their papers. Casey: We could accept initial submissions in standard word processor documents and have our layout editors convert accepted papers into LaTeX. Blair: Accepting standard word documents removes technical barriers for authors while preserving high publishing standards. Alex: I will update the author submission guidelines on the journal website to reflect the flexible format policy.', NULL, NULL, 'Alex proposes: We should require all undergraduate journal authors to submit manuscripts exclusively in LaTeX formatting. Blair raises a concern: Most humanities and social science undergraduates have never used LaTeX and will be discouraged from submitting their papers. Casey suggests a compromise: We could accept initial submissions in standard word processor documents and have our layout editors convert accepted papers into LaTeX. The agreed next step is: I will update the author submission guidelines on the journal website to reflect the flexible format policy.', 10, 120, 15, 'medium', 'Include Alex''s initial proposal, Blair''s practical objection, Casey''s compromise solution, and the agreed next step.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Summarise Group Discussion'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-001', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'A broken balance in the laboratory', 'You are working in the university chemistry laboratory and the electronic analytical balance starts displaying error codes, preventing your group from weighing reagents. Speak to the laboratory technician, explain the problem, and ask if an alternative balance is available. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You are working in the university chemistry laboratory and the electronic analytical balance starts displaying error codes, preventing your group from weighing reagents. Speak to the laboratory technician, explain the problem, and ask if an alternative balance is available.', 'You are working in the university chemistry laboratory and the electronic analytical balance starts displaying error codes, preventing your group from weighing reagents. Speak to the laboratory technician, explain the problem, and ask if an alternative balance is available.', NULL, NULL, 'Hello, excuse me. I''m working on the experiment at bench four, and our analytical balance keeps flashing an error code and won''t tare properly. We need to weigh our reagents to continue. Could you please take a look at it, or is there an alternative balance we could use in the meantime?', 20, 40, 15, 'medium', 'Clearly state the lab bench location, describe the technical error, and politely inquire about a technician check or alternative equipment.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-002', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'A reserved book is missing', 'You reserved a required reference book through the library catalogue two days ago, but the holding shelf has no record of your reservation and the book is not there. Speak to the librarian at the circulation desk, explain your situation, and ask how you can access the text. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You reserved a required reference book through the library catalogue two days ago, but the holding shelf has no record of your reservation and the book is not there. Speak to the librarian at the circulation desk, explain your situation, and ask how you can access the text.', 'You reserved a required reference book through the library catalogue two days ago, but the holding shelf has no record of your reservation and the book is not there. Speak to the librarian at the circulation desk, explain your situation, and ask how you can access the text.', NULL, NULL, 'Hi, good morning. I placed a reservation for the environmental economics textbook two days ago and received a confirmation email, but it wasn''t on the holding shelf. Could you check the system to see if it''s been misplaced, or let me know if a digital reserve copy is available?', 20, 40, 15, 'medium', 'Mention the confirmation email, describe the missing hold, and politely request a catalogue status check or digital reserve copy.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-003', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'A car blocking your driveway', 'You need to leave for an important appointment, but a neighbour''s visitor has parked across your driveway and you cannot get your car out. Speak to your neighbour, explain the problem politely, and ask for the car to be moved. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You need to leave for an important appointment, but a neighbour''s visitor has parked across your driveway and you cannot get your car out. Speak to your neighbour, explain the problem politely, and ask for the car to be moved.', 'You need to leave for an important appointment, but a neighbour''s visitor has parked across your driveway and you cannot get your car out. Speak to your neighbour, explain the problem politely, and ask for the car to be moved.', NULL, NULL, 'Hi, sorry to bother you. I think the silver car across my driveway belongs to one of your visitors. I need to leave for an appointment in about ten minutes, so could you ask them to move it, please? Thanks so much.', 20, 40, 15, 'medium', 'Identify the car, explain the urgency calmly, and make a polite, specific request without blaming anyone.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-004', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'A broken radiator in your room', 'The radiator in your dormitory bedroom has stopped working during a cold winter weekend, leaving your room uncomfortably cold. Visit the residential accommodation office, report the breakdown, and ask when a maintenance engineer can attend to it. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'The radiator in your dormitory bedroom has stopped working during a cold winter weekend, leaving your room uncomfortably cold. Visit the residential accommodation office, report the breakdown, and ask when a maintenance engineer can attend to it.', 'The radiator in your dormitory bedroom has stopped working during a cold winter weekend, leaving your room uncomfortably cold. Visit the residential accommodation office, report the breakdown, and ask when a maintenance engineer can attend to it.', NULL, NULL, 'Hello, I''m a resident in room 302 of Maple Hall. The radiator in my room completely stopped working yesterday, and it''s become extremely cold. Could you please send a maintenance technician to inspect it today, or provide a temporary portable heater while it gets repaired?', 20, 40, 15, 'medium', 'Provide your room number and building, explain the lack of heating, and request urgent maintenance or a temporary heater.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-005', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'The submission website crashes', 'The online course portal crashed five minutes before the midnight deadline while you were uploading your final history essay. It is now the next morning. Speak to your course lecturer, explain what happened with the portal, and provide proof of your timely completion. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'The online course portal crashed five minutes before the midnight deadline while you were uploading your final history essay. It is now the next morning. Speak to your course lecturer, explain what happened with the portal, and provide proof of your timely completion.', 'The online course portal crashed five minutes before the midnight deadline while you were uploading your final history essay. It is now the next morning. Speak to your course lecturer, explain what happened with the portal, and provide proof of your timely completion.', NULL, NULL, 'Good morning Professor Miller. I wanted to speak with you regarding the history essay due last night. The university portal crashed while I was uploading my paper at 11:55 PM. I took a timestamped screenshot of the error and emailed my essay directly to you at that time. Could you please accept the submission without late penalties?', 20, 40, 15, 'medium', 'Politely describe the technical outage, reference your timestamped evidence, and confirm your completed paper was submitted.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-006', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Checking a meal for peanuts', 'You have a severe peanut allergy and want to order lunch from the campus cafeteria hot food station, but none of the dishes have allergen labels. Speak to the cafeteria chef, explain your allergy, and ask which dishes are safe for you to eat. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You have a severe peanut allergy and want to order lunch from the campus cafeteria hot food station, but none of the dishes have allergen labels. Speak to the cafeteria chef, explain your allergy, and ask which dishes are safe for you to eat.', 'You have a severe peanut allergy and want to order lunch from the campus cafeteria hot food station, but none of the dishes have allergen labels. Speak to the cafeteria chef, explain your allergy, and ask which dishes are safe for you to eat.', NULL, NULL, 'Excuse me, chef. I have a severe peanut allergy and noticed there are no allergen labels on the hot counter today. Could you please tell me which dishes are prepared completely free of peanuts and peanut oils, and whether there''s any risk of cross-contamination?', 20, 40, 15, 'medium', 'Clearly state the severe peanut allergy, ask about ingredients and cross-contamination risks, and maintain a polite, safety-conscious tone.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-007', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Someone else is in your booked room', 'You and your project group reserved a library study room for two o''clock, but when you arrive, another student group is already using the room and claims they booked it too. Speak to the group politely, show your reservation confirmation, and suggest a resolution. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You and your project group reserved a library study room for two o''clock, but when you arrive, another student group is already using the room and claims they booked it too. Speak to the group politely, show your reservation confirmation, and suggest a resolution.', 'You and your project group reserved a library study room for two o''clock, but when you arrive, another student group is already using the room and claims they booked it too. Speak to the group politely, show your reservation confirmation, and suggest a resolution.', NULL, NULL, 'Hi there. Excuse me, but we actually have this room booked starting at two o''clock. Here is our booking confirmation email from the library portal. Did your reservation just end, or is there a double booking in the system? Perhaps we could check with the front desk together to sort it out.', 20, 40, 15, 'medium', 'Remain calm and polite, reference your confirmed booking, and suggest checking with library staff to resolve the overlap.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-008', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Asking for a day off for a wedding', 'Your cousin is getting married next month on a Friday, when you are normally scheduled to work at a café. Speak to your manager, explain the situation, and ask whether you can have the day off. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'Your cousin is getting married next month on a Friday, when you are normally scheduled to work at a café. Speak to your manager, explain the situation, and ask whether you can have the day off.', 'Your cousin is getting married next month on a Friday, when you are normally scheduled to work at a café. Speak to your manager, explain the situation, and ask whether you can have the day off.', NULL, NULL, 'Hi, do you have a minute? My cousin is getting married on Friday the twelfth next month, and I''d really like to be there. Would it be possible to have that day off? I''m happy to work an extra shift another day or swap with someone.', 20, 40, 15, 'medium', 'Give plenty of notice, explain the reason briefly, ask politely, and offer a way to cover the shift.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-009', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Turning down a party invitation', 'A friend has invited you to their birthday party on Saturday night, but you have an important exam early on Monday and need the weekend to study. Speak to your friend, thank them, and explain why you cannot come. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'A friend has invited you to their birthday party on Saturday night, but you have an important exam early on Monday and need the weekend to study. Speak to your friend, thank them, and explain why you cannot come.', 'A friend has invited you to their birthday party on Saturday night, but you have an important exam early on Monday and need the weekend to study. Speak to your friend, thank them, and explain why you cannot come.', NULL, NULL, 'Thanks so much for inviting me, I really appreciate it. Unfortunately I''ve got a big exam first thing on Monday and I need to spend the weekend revising. I''m sorry to miss it. Could we go out for a meal to celebrate after my exam?', 20, 40, 15, 'medium', 'Thank your friend, give the reason honestly, express regret, and suggest another way to celebrate.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-010', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'A work shift clashes with a class', 'You work part-time at the campus bookstore, and your manager has scheduled you to work during a newly scheduled compulsory exam review session next Thursday. Speak to your manager, explain the situation, and offer to swap shifts with a colleague. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You work part-time at the campus bookstore, and your manager has scheduled you to work during a newly scheduled compulsory exam review session next Thursday. Speak to your manager, explain the situation, and offer to swap shifts with a colleague.', 'You work part-time at the campus bookstore, and your manager has scheduled you to work during a newly scheduled compulsory exam review session next Thursday. Speak to your manager, explain the situation, and offer to swap shifts with a colleague.', NULL, NULL, 'Hi Sarah, thank you for putting up the weekly schedule. I noticed I''m rostered for Thursday afternoon, but our professor just scheduled a mandatory exam review session during that exact time. I spoke with David, and he''s happy to swap shifts with me so I can cover his Friday morning shift instead. Would that be okay with you?', 20, 40, 15, 'medium', 'Express gratitude for the roster, explain the academic obligation, and present a pre-arranged swap with a coworker to minimize inconvenience.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-011', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'A leaking tap in your flat', 'The kitchen tap in your rented flat has been dripping constantly for a week, and it is getting worse. Call your landlord, describe the problem, and ask when it can be repaired. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'The kitchen tap in your rented flat has been dripping constantly for a week, and it is getting worse. Call your landlord, describe the problem, and ask when it can be repaired.', 'The kitchen tap in your rented flat has been dripping constantly for a week, and it is getting worse. Call your landlord, describe the problem, and ask when it can be repaired.', NULL, NULL, 'Hello, it''s the tenant at flat three. I''m calling because the kitchen tap has been dripping non-stop for about a week and it''s getting worse, so it''s wasting quite a lot of water. Could you arrange for someone to repair it? I''m at home most evenings if that helps.', 20, 40, 15, 'medium', 'Say who you are, describe the fault and how long it has lasted, explain why it matters, and suggest times for the repair.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-012', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Charged twice for textbooks', 'You bought three textbooks at the campus bookstore and just noticed on your receipt that you were charged twice for the most expensive book. Return to the bookstore customer service counter, show your receipt, and request a refund for the duplicate charge. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You bought three textbooks at the campus bookstore and just noticed on your receipt that you were charged twice for the most expensive book. Return to the bookstore customer service counter, show your receipt, and request a refund for the duplicate charge.', 'You bought three textbooks at the campus bookstore and just noticed on your receipt that you were charged twice for the most expensive book. Return to the bookstore customer service counter, show your receipt, and request a refund for the duplicate charge.', NULL, NULL, 'Hello, I just bought these textbooks a few minutes ago, but when I checked my receipt, I noticed that the biology textbook was scanned twice. I only purchased one copy. Here are the three books and my receipt. Could you please process a refund for the extra charge back to my card?', 20, 40, 15, 'medium', 'Politely show the receipt and items, clearly explain the duplicate scan error, and ask for the refund to be processed.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-013', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Asking a neighbour to take in a parcel', 'You are expecting an important parcel tomorrow, but you will be at work all day. Ask your neighbour if they would be willing to accept the delivery for you. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You are expecting an important parcel tomorrow, but you will be at work all day. Ask your neighbour if they would be willing to accept the delivery for you.', 'You are expecting an important parcel tomorrow, but you will be at work all day. Ask your neighbour if they would be willing to accept the delivery for you.', NULL, NULL, 'Hi, I''m sorry to ask a favour, but I''m expecting a parcel tomorrow and I''ll be at work all day. Would you mind taking it in for me if you''re at home? I''ll come and collect it as soon as I''m back in the evening. Thank you so much.', 20, 40, 15, 'medium', 'Apologise for asking, explain when and why, make a clear request and say when you will collect it.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-014', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'A bike locked to a handrail', 'You locked your bicycle to a handrail near the lecture theatre because all the bike racks were full, and a campus security officer is about to impound it. Speak to the officer, apologize, explain the situation, and offer to move the bike immediately. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You locked your bicycle to a handrail near the lecture theatre because all the bike racks were full, and a campus security officer is about to impound it. Speak to the officer, apologize, explain the situation, and offer to move the bike immediately.', 'You locked your bicycle to a handrail near the lecture theatre because all the bike racks were full, and a campus security officer is about to impound it. Speak to the officer, apologize, explain the situation, and offer to move the bike immediately.', NULL, NULL, 'Excuse me, officer. I''m so sorry, that''s my bicycle. All the designated bike racks outside the hall were completely full and I was rushing to take an exam. I understand it shouldn''t be locked to the handrail. If you give me just one moment, I will unlock it right now and move it to the secondary bike rack across the courtyard.', 20, 40, 15, 'medium', 'Acknowledge the violation politely, explain the full bike racks without being defensive, and offer immediate compliance.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-015', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Asking to swap seats on a train', 'You are travelling on a busy train with your young child, but your reserved seats are not together. Ask the passenger sitting next to your child if they would mind changing seats with you. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You are travelling on a busy train with your young child, but your reserved seats are not together. Ask the passenger sitting next to your child if they would mind changing seats with you.', 'You are travelling on a busy train with your young child, but your reserved seats are not together. Ask the passenger sitting next to your child if they would mind changing seats with you.', NULL, NULL, 'Excuse me, I''m sorry to trouble you. My daughter is sitting next to you and my reserved seat is two rows back, by the window. Would you mind swapping with me so I can sit with her? Thank you, that''s very kind.', 20, 40, 15, 'medium', 'Explain the situation briefly, describe the other seat so it sounds fair, ask politely and thank the passenger.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-016', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'A jammed printer', 'The high-volume printer in the university computer lab has jammed with crumpled paper while you were printing your senior thesis, and several other students are waiting behind you. Speak to the lab assistant, describe the jam, and ask for technical assistance. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'The high-volume printer in the university computer lab has jammed with crumpled paper while you were printing your senior thesis, and several other students are waiting behind you. Speak to the lab assistant, describe the jam, and ask for technical assistance.', 'The high-volume printer in the university computer lab has jammed with crumpled paper while you were printing your senior thesis, and several other students are waiting behind you. Speak to the lab assistant, describe the jam, and ask for technical assistance.', NULL, NULL, 'Hi, excuse me. The main laser printer just had a paper jam while printing my document, and there''s paper stuck inside tray two. A few other students are also waiting in line. Could you please help clear the jam and ensure our queued documents aren''t canceled?', 20, 40, 15, 'medium', 'Explain the specific location of the paper jam, mention the waiting queue, and ask the technician to assist and check print queues.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-017', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Late for a lab because of a train', 'Your morning commuter train was delayed by forty minutes due to signal failure, causing you to arrive late for a mandatory chemistry laboratory safety briefing. Approach the teaching assistant, explain the transit delay, and ask if you can join the lab. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'Your morning commuter train was delayed by forty minutes due to signal failure, causing you to arrive late for a mandatory chemistry laboratory safety briefing. Approach the teaching assistant, explain the transit delay, and ask if you can join the lab.', 'Your morning commuter train was delayed by forty minutes due to signal failure, causing you to arrive late for a mandatory chemistry laboratory safety briefing. Approach the teaching assistant, explain the transit delay, and ask if you can join the lab.', NULL, NULL, 'Good morning, I apologize for arriving late. My commuter train was halted for forty minutes due to a track signal failure. I know the safety briefing was scheduled for the first ten minutes. Could you please give me a quick safety briefing so I can participate in today''s experiment safely?', 20, 40, 15, 'medium', 'Apologize sincerely, explain the train delay, acknowledge safety protocol importance, and ask for a brief overview to participate safely.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-018', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'A forgotten locker code', 'You forgot the combination to your rented gym locker in the campus sports complex and your student ID and car keys are locked inside. Speak to the sports center receptionist, prove your identity, and ask to have the locker opened. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You forgot the combination to your rented gym locker in the campus sports complex and your student ID and car keys are locked inside. Speak to the sports center receptionist, prove your identity, and ask to have the locker opened.', 'You forgot the combination to your rented gym locker in the campus sports complex and your student ID and car keys are locked inside. Speak to the sports center receptionist, prove your identity, and ask to have the locker opened.', NULL, NULL, 'Hello, I''m having a problem with locker 45 in the men''s changing room. My locker combination has slipped my mind, and my student ID and car keys are inside. I have a photo of my student card on my phone to verify that the locker is registered to my name. Could someone with the master key help me open it?', 20, 40, 15, 'medium', 'State the locker number, explain the forgotten code and trapped essentials, offer phone verification, and request master key help.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-019', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Needing a transcript urgently', 'You need an official academic transcript stamped by the university registrar for a scholarship deadline tomorrow, but the standard processing time is five business days. Speak to the records officer, explain the urgent scholarship deadline, and ask if expedited processing is possible. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You need an official academic transcript stamped by the university registrar for a scholarship deadline tomorrow, but the standard processing time is five business days. Speak to the records officer, explain the urgent scholarship deadline, and ask if expedited processing is possible.', 'You need an official academic transcript stamped by the university registrar for a scholarship deadline tomorrow, but the standard processing time is five business days. Speak to the records officer, explain the urgent scholarship deadline, and ask if expedited processing is possible.', NULL, NULL, 'Good morning. I urgently need an official stamped transcript for an external scholarship application with a strict deadline tomorrow afternoon. I realize standard processing takes five days, but is there any possibility of paying an expedited fee or having a copy certified today? This scholarship is critical for my tuition.', 20, 40, 15, 'medium', 'Politely describe the urgent scholarship deadline, acknowledge standard turnaround times, and ask about expedited or same-day processing.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-020', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'A damaged camera kit', 'While checking out a camera kit from the university media department, you notice the lens filter is cracked and the battery charger is missing. Speak to the equipment coordinator before leaving so you are not blamed for the damage. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'While checking out a camera kit from the university media department, you notice the lens filter is cracked and the battery charger is missing. Speak to the equipment coordinator before leaving so you are not blamed for the damage.', 'While checking out a camera kit from the university media department, you notice the lens filter is cracked and the battery charger is missing. Speak to the equipment coordinator before leaving so you are not blamed for the damage.', NULL, NULL, 'Hi, before I sign out this camera kit, I wanted to point out that the UV filter on the 50mm lens is already cracked, and the battery charger seems to be missing from the case. Could you please note this pre-existing damage on the checkout log so I''m not held responsible when returning it?', 20, 40, 15, 'medium', 'Point out the pre-existing damage proactively, verify missing parts, and ensure it is documented on the equipment log.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-021', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Cold air in a lecture hall', 'Your regular lecture hall has an air conditioning system that is blowing freezing air directly onto students, making it impossible to concentrate during a two-hour lecture. Speak to the building facilities manager and ask if the thermostat can be adjusted. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'Your regular lecture hall has an air conditioning system that is blowing freezing air directly onto students, making it impossible to concentrate during a two-hour lecture. Speak to the building facilities manager and ask if the thermostat can be adjusted.', 'Your regular lecture hall has an air conditioning system that is blowing freezing air directly onto students, making it impossible to concentrate during a two-hour lecture. Speak to the building facilities manager and ask if the thermostat can be adjusted.', NULL, NULL, 'Hello, I''m a student in lecture hall B12. The air conditioning in that room is currently set extremely low and blowing freezing air directly over the seating area. Most students are shivering and finding it hard to take notes. Could you please adjust the thermostat to a more comfortable temperature?', 20, 40, 15, 'medium', 'Specify the exact room number, describe the discomfort affecting students'' focus, and request a thermostat adjustment.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-022', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Changing your open day hours', 'You volunteered to help staff the campus open day welcome booth from 9 AM to 3 PM, but you were just assigned a mandatory academic advising appointment at 1 PM. Speak to the volunteer coordinator, explain the conflict, and offer to work the morning shift. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You volunteered to help staff the campus open day welcome booth from 9 AM to 3 PM, but you were just assigned a mandatory academic advising appointment at 1 PM. Speak to the volunteer coordinator, explain the conflict, and offer to work the morning shift.', 'You volunteered to help staff the campus open day welcome booth from 9 AM to 3 PM, but you were just assigned a mandatory academic advising appointment at 1 PM. Speak to the volunteer coordinator, explain the conflict, and offer to work the morning shift.', NULL, NULL, 'Hi Rebecca, regarding the open day welcome desk this Saturday: I was just scheduled for a mandatory academic advising appointment at one o''clock. Would it be alright if I work the morning shift from nine until twelve-thirty? That way I can still help welcome the largest rush of morning visitors.', 20, 40, 15, 'medium', 'Explain the newly scheduled academic appointment, propose a concrete morning shift commitment, and ensure the booth remains staffed.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-023', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'The wrong size graduation gown', 'You picked up your rented graduation cap and gown from the campus bookstore, but upon trying it on at home, you realized the gown is much too long and drags on the floor. Return to the distribution desk, explain the issue, and request a smaller size. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You picked up your rented graduation cap and gown from the campus bookstore, but upon trying it on at home, you realized the gown is much too long and drags on the floor. Return to the distribution desk, explain the issue, and request a smaller size.', 'You picked up your rented graduation cap and gown from the campus bookstore, but upon trying it on at home, you realized the gown is much too long and drags on the floor. Return to the distribution desk, explain the issue, and request a smaller size.', NULL, NULL, 'Hello, I picked up this graduation gown yesterday, but when I tried it on, it turned out to be far too long and drags on the floor when I walk. Here is my rental receipt. Would it be possible to exchange it for a medium size that fits my height properly?', 20, 40, 15, 'medium', 'Politely present the gown and receipt, explain the sizing issue, and request an exchange for the correct fit.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-024', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Changing a restaurant booking', 'You booked a table for four people at a restaurant for seven o''clock tonight, but your train is delayed and you will arrive later. Call the restaurant and ask to change the booking time. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You booked a table for four people at a restaurant for seven o''clock tonight, but your train is delayed and you will arrive later. Call the restaurant and ask to change the booking time.', 'You booked a table for four people at a restaurant for seven o''clock tonight, but your train is delayed and you will arrive later. Call the restaurant and ask to change the booking time.', NULL, NULL, 'Hello, I have a booking for four people at seven o''clock tonight under the name Karki. Our train has been delayed, so we won''t arrive until about half past eight. Would it be possible to move the booking to then? If not, is there another time you could offer us?', 20, 40, 15, 'medium', 'Give the booking details, explain the delay, ask for a specific new time and show flexibility.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-025', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'A wallet left on the shuttle bus', 'You accidentally left your leather wallet on the campus shuttle bus twenty minutes ago. Contact the university transit dispatch office, describe the wallet and the bus route you took, and ask if any driver has turned it in. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You accidentally left your leather wallet on the campus shuttle bus twenty minutes ago. Contact the university transit dispatch office, describe the wallet and the bus route you took, and ask if any driver has turned it in.', 'You accidentally left your leather wallet on the campus shuttle bus twenty minutes ago. Contact the university transit dispatch office, describe the wallet and the bus route you took, and ask if any driver has turned it in.', NULL, NULL, 'Hello transit dispatch. I just got off the North Campus shuttle bus twenty minutes ago at the science building, and I believe I left my brown leather wallet on one of the middle seats. It has my driver''s license and student ID inside. Has the driver reported finding any lost items on that route?', 20, 40, 15, 'medium', 'State the bus route, stop, and time accurately, provide an identifying description of the wallet and contents, and ask dispatch to check.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-026', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Recording lectures with a broken wrist', 'You have a broken wrist and are temporarily unable to handwrite or type lecture notes fast enough to keep up. Speak to your economics professor after class, explain your physical impairment, and ask for permission to audio record lectures. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You have a broken wrist and are temporarily unable to handwrite or type lecture notes fast enough to keep up. Speak to your economics professor after class, explain your physical impairment, and ask for permission to audio record lectures.', 'You have a broken wrist and are temporarily unable to handwrite or type lecture notes fast enough to keep up. Speak to your economics professor after class, explain your physical impairment, and ask for permission to audio record lectures.', NULL, NULL, 'Hello Professor Adams. As you can see, I recently fractured my right wrist and have it in a cast, which makes handwriting or typing notes very difficult right now. Would you mind if I place a small voice recorder on the podium to record your lectures solely for my personal study until my cast is removed?', 20, 40, 15, 'medium', 'Explain the physical injury, assure the professor the recording is strictly for personal study, and ask for permission respectfully.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-027', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'A wrong charge on your meal plan', 'You checked your campus meal plan balance online and noticed a charge of thirty-five dollars from the campus grill that you did not make. Speak to the dining services cashier supervisor, show your account statement, and ask for the error to be investigated. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You checked your campus meal plan balance online and noticed a charge of thirty-five dollars from the campus grill that you did not make. Speak to the dining services cashier supervisor, show your account statement, and ask for the error to be investigated.', 'You checked your campus meal plan balance online and noticed a charge of thirty-five dollars from the campus grill that you did not make. Speak to the dining services cashier supervisor, show your account statement, and ask for the error to be investigated.', NULL, NULL, 'Hi, I''m checking my student meal account and noticed a charge of thirty-five dollars at the campus grill yesterday afternoon at three PM, but I was in a biology lecture across campus at that time. Could you please look into this transaction and see if another student''s order was mistakenly charged to my student number?', 20, 40, 15, 'medium', 'Explain the incorrect charge, specify the date and time, mention your conflicting class, and politely ask for an account audit.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-028', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Inviting a classmate to a study group', 'You notice a classmate who consistently asks insightful questions during complex organic chemistry lectures. Speak to them after class, compliment their contributions, and invite them to join your weekly study group. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You notice a classmate who consistently asks insightful questions during complex organic chemistry lectures. Speak to them after class, compliment their contributions, and invite them to join your weekly study group.', 'You notice a classmate who consistently asks insightful questions during complex organic chemistry lectures. Speak to them after class, compliment their contributions, and invite them to join your weekly study group.', NULL, NULL, 'Hey David, I really liked the question you asked today about reaction mechanisms—it helped clear up a lot of confusion. A few of us from class meet every Wednesday evening at the library for a study group to work through problem sets. Would you be interested in joining us this week?', 20, 40, 15, 'medium', 'Pay a genuine compliment regarding their class contribution, explain the weekly study group format, and extend a friendly invitation.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-029', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'A vending machine takes your money', 'You put four dollars into the snack vending machine in the engineering building lobby, but the spiral coil jammed halfway, taking your money without releasing the snack. Speak to the building reception desk, report the machine number, and ask about a refund. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You put four dollars into the snack vending machine in the engineering building lobby, but the spiral coil jammed halfway, taking your money without releasing the snack. Speak to the building reception desk, report the machine number, and ask about a refund.', 'You put four dollars into the snack vending machine in the engineering building lobby, but the spiral coil jammed halfway, taking your money without releasing the snack. Speak to the building reception desk, report the machine number, and ask about a refund.', NULL, NULL, 'Hello, I just tried to buy a snack from the vending machine in the lobby, machine number four, but the coil jammed halfway and didn''t dispense the item, even though it took my four dollars. Is there a refund slip I can fill out, or a contact number for the vendor to get that resolved?', 20, 40, 15, 'medium', 'State the machine number, explain the jam and lost money, and inquire about the standard refund procedure.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-030', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Missing the field trip bus', 'You arrived at the departmental field trip meeting point three minutes late due to a subway delay, and the main group bus has just departed. Phone the field trip organizer, apologize for being late, and ask if you can meet the group at the first field site. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You arrived at the departmental field trip meeting point three minutes late due to a subway delay, and the main group bus has just departed. Phone the field trip organizer, apologize for being late, and ask if you can meet the group at the first field site.', 'You arrived at the departmental field trip meeting point three minutes late due to a subway delay, and the main group bus has just departed. Phone the field trip organizer, apologize for being late, and ask if you can meet the group at the first field site.', NULL, NULL, 'Hello Dr. Patel, this is Emily. I''m so sorry, my subway was delayed and I arrived at the campus pickup point just as your bus pulled away. I know the first stop is the geological quarry at ten AM. If I take the regional bus right now, I can meet you at the quarry gate by 9:50. Would that be acceptable?', 20, 40, 15, 'medium', 'Apologize for missing the departure, explain the subway delay, and present an immediate independent travel plan to rejoin the group on time.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-031', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'A roommate''s guest who stays for days', 'Your roommate has had an overnight guest staying in your shared room for four consecutive days without asking you first, making it difficult to study and sleep. Speak to your roommate calmly, describe how it affects you, and suggest a fair guest policy. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'Your roommate has had an overnight guest staying in your shared room for four consecutive days without asking you first, making it difficult to study and sleep. Speak to your roommate calmly, describe how it affects you, and suggest a fair guest policy.', 'Your roommate has had an overnight guest staying in your shared room for four consecutive days without asking you first, making it difficult to study and sleep. Speak to your roommate calmly, describe how it affects you, and suggest a fair guest policy.', NULL, NULL, 'Hey Sam, do you have a few minutes to talk? Having your friend stay over for the past four nights has made it hard for me to study and get enough rest in our shared room. I don''t mind having guests over occasionally, but could we agree to limit overnight guests to weekends and check with each other beforehand?', 20, 40, 15, 'medium', 'Remain calm and reasonable, express how extended guests impact privacy and study, and propose a sensible weekend guest rule.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-032', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'A fine for a book you returned', 'The library account shows a twenty-dollar overdue fine for a book that you returned into the exterior drop box three days before the due date. Speak to the library circulation desk supervisor, explain the timeline, and ask to have the fine waived. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'The library account shows a twenty-dollar overdue fine for a book that you returned into the exterior drop box three days before the due date. Speak to the library circulation desk supervisor, explain the timeline, and ask to have the fine waived.', 'The library account shows a twenty-dollar overdue fine for a book that you returned into the exterior drop box three days before the due date. Speak to the library circulation desk supervisor, explain the timeline, and ask to have the fine waived.', NULL, NULL, 'Good morning. My account shows an overdue fine for the modern history textbook, but I returned it into the library drop box on Friday evening, well before the Monday due date. It looks like it wasn''t scanned in until Tuesday morning. Could you please check the return log and waive this fee?', 20, 40, 15, 'medium', 'Explain when the book was deposited in the drop box versus when it was checked in, and politely ask to waive the erroneous fine.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-033', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Asking which textbooks to buy', 'You are trying to budget for course textbooks before the semester starts and want to know which books are mandatory. Email or speak to your upcoming literature professor, introduce yourself, and ask if the syllabus is available early. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You are trying to budget for course textbooks before the semester starts and want to know which books are mandatory. Email or speak to your upcoming literature professor, introduce yourself, and ask if the syllabus is available early.', 'You are trying to budget for course textbooks before the semester starts and want to know which books are mandatory. Email or speak to your upcoming literature professor, introduce yourself, and ask if the syllabus is available early.', NULL, NULL, 'Hello Professor Higgins, my name is Alex and I''m enrolled in your Victorian Literature seminar this autumn. I''m currently organizing my semester budget and looking for second-hand textbooks. Would it be possible to see a preliminary copy of the reading list or syllabus so I can order the required novels in advance?', 20, 40, 15, 'medium', 'Introduce yourself politely, explain the practical reason for wanting the reading list early, and request a preliminary syllabus.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-034', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Following up a job application', 'You submitted an application for a student assistant position at the university international office two weeks ago and haven''t heard back. Visit the office, speak to the hiring coordinator, and politely inquire about the status of your application. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You submitted an application for a student assistant position at the university international office two weeks ago and haven''t heard back. Visit the office, speak to the hiring coordinator, and politely inquire about the status of your application.', 'You submitted an application for a student assistant position at the university international office two weeks ago and haven''t heard back. Visit the office, speak to the hiring coordinator, and politely inquire about the status of your application.', NULL, NULL, 'Good afternoon. My name is Carlos and I submitted an application two weeks ago for the student assistant position in the international office. I wanted to follow up and see if the search committee has begun reviewing applications, and whether you need any additional documents from my end.', 20, 40, 15, 'medium', 'State your name and the position applied for, ask politely about the hiring timeline, and offer any extra information.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-035', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'A broken window blind', 'The roller blind in your dorm room snapped when you tried to pull it down last night, leaving your window unshaded from the streetlights. Report the issue to the residence hall maintenance portal supervisor and request a repair. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'The roller blind in your dorm room snapped when you tried to pull it down last night, leaving your window unshaded from the streetlights. Report the issue to the residence hall maintenance portal supervisor and request a repair.', 'The roller blind in your dorm room snapped when you tried to pull it down last night, leaving your window unshaded from the streetlights. Report the issue to the residence hall maintenance portal supervisor and request a repair.', NULL, NULL, 'Hi, I live in room 214 of West Hall. The cord on the window roller blind snapped last night while I was closing it, and now it''s stuck completely open. The bright streetlights right outside make it very difficult to sleep. Could you please submit an urgent work order to have the blind repaired or replaced?', 20, 40, 15, 'medium', 'Give the room number, explain that the blind snapped and is stuck open, mention street light glare, and request maintenance.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-036', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Asking for more club funding', 'The student council finance committee allocated only half of the requested funding for your environmental club''s annual campus recycling festival. Meet with the treasurer, present your detailed itemized budget, and appeal for additional funding. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'The student council finance committee allocated only half of the requested funding for your environmental club''s annual campus recycling festival. Meet with the treasurer, present your detailed itemized budget, and appeal for additional funding.', 'The student council finance committee allocated only half of the requested funding for your environmental club''s annual campus recycling festival. Meet with the treasurer, present your detailed itemized budget, and appeal for additional funding.', NULL, NULL, 'Hello, thank you for meeting with me. Our environmental club received the allocation notice for the recycling festival, and we noticed our budget was reduced by half. We''ve prepared an itemized breakdown showing that venue rental and safety equipment make up our core costs. Could you explain the deduction and reconsider funding the safety portion?', 20, 40, 15, 'medium', 'Express appreciation for the meeting, reference your itemized cost breakdown, and politely appeal for essential funding categories.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-037', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Understanding essay feedback', 'You received a lower grade than expected on your first philosophy essay and don''t understand the written comments. Schedule office hours with your teaching assistant, express your desire to improve, and ask for specific guidance on future essays. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You received a lower grade than expected on your first philosophy essay and don''t understand the written comments. Schedule office hours with your teaching assistant, express your desire to improve, and ask for specific guidance on future essays.', 'You received a lower grade than expected on your first philosophy essay and don''t understand the written comments. Schedule office hours with your teaching assistant, express your desire to improve, and ask for specific guidance on future essays.', NULL, NULL, 'Hello Mr. Davies, thank you for meeting with me. I read through your feedback on my first philosophy paper, but I''m having trouble understanding how to improve my counter-argument structure. I''m keen to do better on the next assignment. Could you walk me through where my analysis fell short and what you''d recommend focusing on?', 20, 40, 15, 'medium', 'Show openness to constructive criticism, mention a specific area of weakness, and ask for guidance to improve on future assignments.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-038', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Missing cutlery for a lunch event', 'You are organizing a student symposium lunch and the catering company just delivered seventy boxed meals but forgot to include any forks, napkins, or drinking cups. Phone the catering manager immediately and request a prompt delivery of the missing supplies. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You are organizing a student symposium lunch and the catering company just delivered seventy boxed meals but forgot to include any forks, napkins, or drinking cups. Phone the catering manager immediately and request a prompt delivery of the missing supplies.', 'You are organizing a student symposium lunch and the catering company just delivered seventy boxed meals but forgot to include any forks, napkins, or drinking cups. Phone the catering manager immediately and request a prompt delivery of the missing supplies.', NULL, NULL, 'Hi, this is Liam from the student symposium in the arts atrium. We just received the delivery of seventy boxed lunches, but the driver forgot all the cutlery, napkins, and cups. Our lunch break starts in twenty minutes. Could you please send someone over with the utensils right away so our guests can eat?', 20, 40, 15, 'medium', 'Identify the event and location, explain the missing utensils, emphasize the urgent 20-minute timeline, and request prompt delivery.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-039', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Cycling past a group on a shared path', 'You are riding your bicycle along a shared pedestrian-cyclist campus path and a group of students wearing headphones is walking three abreast, blocking the path. Alert them politely, ring your bell, and pass safely. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You are riding your bicycle along a shared pedestrian-cyclist campus path and a group of students wearing headphones is walking three abreast, blocking the path. Alert them politely, ring your bell, and pass safely.', 'You are riding your bicycle along a shared pedestrian-cyclist campus path and a group of students wearing headphones is walking three abreast, blocking the path. Alert them politely, ring your bell, and pass safely.', NULL, NULL, 'Excuse me, on your left! Sorry to interrupt, I''m just passing by on a bicycle. Thank you so much, have a great afternoon!', 20, 40, 15, 'medium', 'Give a clear, courteous directional warning (''on your left''), acknowledge the courtesy, and maintain safe cycling speed.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-040', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Asking a professor about research work', 'You attended an inspiring guest lecture by a neurobiology professor and want to ask if she has any volunteer research assistant openings in her lab. Speak to her after the lecture, mention your interest in her topic, and ask about opportunities. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You attended an inspiring guest lecture by a neurobiology professor and want to ask if she has any volunteer research assistant openings in her lab. Speak to her after the lecture, mention your interest in her topic, and ask about opportunities.', 'You attended an inspiring guest lecture by a neurobiology professor and want to ask if she has any volunteer research assistant openings in her lab. Speak to her after the lecture, mention your interest in her topic, and ask about opportunities.', NULL, NULL, 'Professor Zhang, thank you for such an inspiring lecture on synaptic plasticity. I''m a second-year neuroscience student, and I''ve read several of your lab''s recent publications on glial signaling. I was wondering if you might have any volunteer openings for an undergraduate research assistant this semester?', 20, 40, 15, 'medium', 'Express genuine appreciation for the lecture, mention your academic background and interest, and ask politely about research openings.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-041', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Asking a guide to slow down', 'You are on a walking tour of a city with your elderly grandfather, and the guide is walking too fast for him to keep up. Speak to the guide politely and ask whether the group could walk a little more slowly. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You are on a walking tour of a city with your elderly grandfather, and the guide is walking too fast for him to keep up. Speak to the guide politely and ask whether the group could walk a little more slowly.', 'You are on a walking tour of a city with your elderly grandfather, and the guide is walking too fast for him to keep up. Speak to the guide politely and ask whether the group could walk a little more slowly.', NULL, NULL, 'Excuse me, I''m really enjoying the tour, but my grandfather is finding it hard to keep up with the pace. Would it be possible to walk a little more slowly, or to pause for a moment at each stop? That would make a big difference to him. Thank you.', 20, 40, 15, 'medium', 'Start positively, explain the difficulty tactfully, suggest a specific change and thank the guide.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-042', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'No internet in a basement room', 'You and your classmates frequently lose wireless internet connection in the new basement seminar room of the life sciences building. Report the issue to the campus IT help desk, give the room details, and ask if a signal booster can be added. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You and your classmates frequently lose wireless internet connection in the new basement seminar room of the life sciences building. Report the issue to the campus IT help desk, give the room details, and ask if a signal booster can be added.', 'You and your classmates frequently lose wireless internet connection in the new basement seminar room of the life sciences building. Report the issue to the campus IT help desk, give the room details, and ask if a signal booster can be added.', NULL, NULL, 'Hello, I''d like to report a persistent WiFi dead zone. In room B08 of the Life Sciences building, students consistently lose internet connectivity during lectures, which makes accessing online course files impossible. Could the network team check the access points in that basement or install a signal booster?', 20, 40, 15, 'medium', 'Specify the exact building and basement room, describe the recurring connectivity failure, and request an IT technician check or booster.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-043', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Noise in the silent study area', 'Two students are having an animated, loud social conversation in the designated silent study zone of the science library. Approach them politely, remind them of the zone''s quiet rules, and suggest the ground floor cafe. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'Two students are having an animated, loud social conversation in the designated silent study zone of the science library. Approach them politely, remind them of the zone''s quiet rules, and suggest the ground floor cafe.', 'Two students are having an animated, loud social conversation in the designated silent study zone of the science library. Approach them politely, remind them of the zone''s quiet rules, and suggest the ground floor cafe.', NULL, NULL, 'Hi, excuse me. I''m really sorry to interrupt, but this whole floor is designated as a silent study zone and people are trying to prepare for exams. If you need to chat or take a break, there''s plenty of open social seating downstairs in the cafe. Thank you for understanding.', 20, 40, 15, 'medium', 'Use a polite, respectful tone, point out the silent study designation, and suggest an alternative social location.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-044', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Asking to skip a required course', 'You want to enroll in an advanced data science elective, but the system says you lack an introductory statistics prerequisite that you actually completed at your previous college. Speak to your academic advisor, show your transcript, and ask for a prerequisite waiver. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You want to enroll in an advanced data science elective, but the system says you lack an introductory statistics prerequisite that you actually completed at your previous college. Speak to your academic advisor, show your transcript, and ask for a prerequisite waiver.', 'You want to enroll in an advanced data science elective, but the system says you lack an introductory statistics prerequisite that you actually completed at your previous college. Speak to your academic advisor, show your transcript, and ask for a prerequisite waiver.', NULL, NULL, 'Hello Dr. Kelly. I''m trying to enroll in Data Science 301, but the registration system flagged me for missing the introductory statistics prerequisite. I actually completed an equivalent course with an A grade at my previous university. Here is my certified transfer transcript. Could you please grant a prerequisite waiver?', 20, 40, 15, 'medium', 'Explain the registration block, show proof of the equivalent completed coursework on your transfer transcript, and ask for the prerequisite waiver.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-045', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Handing in car keys you found', 'You found a set of car keys with a university gym tag lying on the grass outside the student union. Bring the keys to the campus security office, describe where you found them, and hand them over. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You found a set of car keys with a university gym tag lying on the grass outside the student union. Bring the keys to the campus security office, describe where you found them, and hand them over.', 'You found a set of car keys with a university gym tag lying on the grass outside the student union. Bring the keys to the campus security office, describe where you found them, and hand them over.', NULL, NULL, 'Hello officer, I just found this set of car keys on the lawn right outside the north entrance of the student union about ten minutes ago. There''s a campus gym barcode attached to the keyring, so you might be able to scan it and identify the student who lost them.', 20, 40, 15, 'medium', 'Describe the exact location and time the keys were found, highlight the gym barcode to assist identification, and hand them in.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-046', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Moving an appointment online', 'You have a mandatory academic advising appointment scheduled for 10 AM tomorrow, but you have developed a severe cough and fever. Email or phone your advisor, apologize for the short notice, and ask to reschedule or hold the meeting via video call. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You have a mandatory academic advising appointment scheduled for 10 AM tomorrow, but you have developed a severe cough and fever. Email or phone your advisor, apologize for the short notice, and ask to reschedule or hold the meeting via video call.', 'You have a mandatory academic advising appointment scheduled for 10 AM tomorrow, but you have developed a severe cough and fever. Email or phone your advisor, apologize for the short notice, and ask to reschedule or hold the meeting via video call.', NULL, NULL, 'Good morning Ms. Clark. I apologize for the short notice, but I woke up this morning with a high fever and a severe cough, and I want to avoid spreading illness. Could we possibly conduct our advising appointment via Zoom tomorrow, or reschedule for next week when I''ve recovered?', 20, 40, 15, 'medium', 'Apologize for the short notice, explain illness symptoms courteously, and offer an immediate video call option or future rescheduling.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-047', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'A flooded pitch booking', 'You booked the outdoor soccer pitch for your intramural team tonight, but torrential rain has flooded the field. Call the campus sports recreation desk, explain the weather conditions, and ask to cancel the booking without penalty. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You booked the outdoor soccer pitch for your intramural team tonight, but torrential rain has flooded the field. Call the campus sports recreation desk, explain the weather conditions, and ask to cancel the booking without penalty.', 'You booked the outdoor soccer pitch for your intramural team tonight, but torrential rain has flooded the field. Call the campus sports recreation desk, explain the weather conditions, and ask to cancel the booking without penalty.', NULL, NULL, 'Hello, I booked the outdoor soccer field for seven o''clock tonight under the name Intramural Hawks. With the torrential rain today, the pitch is completely flooded and unplayable. Could we please cancel tonight''s booking and receive a credit towards our next match without paying a cancellation fee?', 20, 40, 15, 'medium', 'Identify the booking name, describe the weather and unplayable field conditions, and politely ask for a penalty-free cancellation or credit.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-048', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Returning a gift without a receipt', 'Someone gave you a jacket as a present, but it is too small and you do not have the receipt. Go to the shop and ask whether you can exchange it for a larger size. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'Someone gave you a jacket as a present, but it is too small and you do not have the receipt. Go to the shop and ask whether you can exchange it for a larger size.', 'Someone gave you a jacket as a present, but it is too small and you do not have the receipt. Go to the shop and ask whether you can exchange it for a larger size.', NULL, NULL, 'Hello, I was given this jacket as a gift, but unfortunately it''s too small for me. I don''t have the receipt, but the labels are still on it. Would it be possible to exchange it for a larger size, or for store credit?', 20, 40, 15, 'medium', 'Explain that it was a gift, mention its condition, ask about an exchange and offer an alternative such as store credit.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-049', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'Storing luggage over the holidays', 'You are an international student living in campus dorms and need a secure place to store your luggage over the three-month summer break. Speak to the housing facilities manager and ask if the university offers summer trunk storage. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You are an international student living in campus dorms and need a secure place to store your luggage over the three-month summer break. Speak to the housing facilities manager and ask if the university offers summer trunk storage.', 'You are an international student living in campus dorms and need a secure place to store your luggage over the three-month summer break. Speak to the housing facilities manager and ask if the university offers summer trunk storage.', NULL, NULL, 'Hello, I''m an international student living in East Hall, and I''ll be flying home for the summer vacation. Does the housing office offer secure summer luggage storage for international residents, or do you have a recommended local storage service that provides student discounts?', 20, 40, 15, 'medium', 'State your international resident status, explain the summer break timing, and inquire about campus storage or discounted partner options.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE),
    ('pte-b3-rts-050', 'pte-2026-01', 'PTE', 'speaking', 'pte-respond-to-situation', 'Respond to a Situation', 'The wrong textbook delivered', 'You ordered a required medical terminology textbook from the university bookstore''s online service, but when the package arrived, it contained an introductory botany manual instead. Return to the bookstore dispatch counter, present the package, and ask for the correct book. In 20 seconds, please prepare your response. You will have 40 seconds to give your response.', 'You ordered a required medical terminology textbook from the university bookstore''s online service, but when the package arrived, it contained an introductory botany manual instead. Return to the bookstore dispatch counter, present the package, and ask for the correct book.', 'You ordered a required medical terminology textbook from the university bookstore''s online service, but when the package arrived, it contained an introductory botany manual instead. Return to the bookstore dispatch counter, present the package, and ask for the correct book.', NULL, NULL, 'Hi, I placed an online order for the Medical Terminology textbook, but when I opened the package this morning, it contained an Introductory Botany book instead. Here is my order confirmation and the packing slip. Could you please exchange this for the correct textbook I ordered?', 20, 40, 15, 'medium', 'Show the order confirmation, explain the packing mistake clearly, and request the immediate exchange for the ordered textbook.', ARRAY['PTE', 'Original practice', 'Batch 3', 'Respond to a Situation'], ARRAY['PTE'], TRUE)
